/* LINER-UPDATE id="board-annotations-v1" title="خانه‌ی سبز/قرمز و فلش دستی روی صفحه (ویرایش) + نمایش در مرور" base="v6" */
(function () {
  if (window.__LINER_ANN) return;
  window.__LINER_ANN = 1;

  var NS = 'http://www.w3.org/2000/svg', F = 'abcdefgh';
  var COL = { g: '#16a34a', r: '#dc2626' };
  var ANN = { mode: null, start: null, cur: null };

  LU.css(
    '.board .sq.ang{background-image:linear-gradient(rgba(34,197,94,.62),rgba(34,197,94,.62))}' +
    '.board .sq.anr{background-image:linear-gradient(rgba(239,68,68,.62),rgba(239,68,68,.62))}' +
    '#anbar{margin:8px 0}' +
    '#anbar[hidden]{display:none}' +
    '#anbar .anr1{display:flex;gap:6px;flex-wrap:wrap}' +
    '#anbar button{flex:1 1 auto;min-width:0}' +
    '#anbar button.on{outline:2px solid var(--acc)}' +
    '#anbar .g{background:#16a34a;color:#fff}#anbar .r{background:#dc2626;color:#fff}'
  );

  /* ---------- نوار ابزار (فقط در ویرایش) ---------- */
  var fs2 = $('fs2'), bd2 = $('bd2');
  if (!fs2 || !bd2) throw new Error('عناصر ویرایش پیدا نشد');
  var btn = document.createElement('button');
  btn.type = 'button'; btn.id = 'anbtn'; btn.textContent = '🎨 خانه و فلش';
  fs2.insertAdjacentElement('afterend', btn);
  var bar = document.createElement('div');
  bar.id = 'anbar'; bar.hidden = true;
  bar.innerHTML =
    '<div class="anr1">' +
    '<button type="button" class="g" data-m="sg">■ خانه سبز</button>' +
    '<button type="button" class="r" data-m="sr">■ خانه قرمز</button>' +
    '<button type="button" class="g" data-m="ag">➚ فلش سبز</button>' +
    '<button type="button" class="r" data-m="ar">➚ فلش قرمز</button>' +
    '<button type="button" data-m="clr">پاک‌کردن این پوزیشن</button></div>' +
    '<div class="meta" id="anh" style="margin-top:4px"></div>';
  bd2.parentNode.insertAdjacentElement('afterend', bar);

  var HINT = {
    sg: 'روی هر خانه بزن تا سبز بشه (دوباره بزنی برمی‌داره).',
    sr: 'روی هر خانه بزن تا قرمز بشه (دوباره بزنی برمی‌داره).',
    ag: 'از خانه‌ی مبدأ تا مقصد بکش تا فلش سبز ساخته بشه (دوباره همونو بکشی برمی‌داره).',
    ar: 'از خانه‌ی مبدأ تا مقصد بکش تا فلش قرمز ساخته بشه (دوباره همونو بکشی برمی‌داره).'
  };
  function sync() {
    Array.prototype.forEach.call(bar.querySelectorAll('[data-m]'), function (b) { b.classList.toggle('on', b.dataset.m === ANN.mode); });
    $('anh').textContent = ANN.mode ? HINT[ANN.mode] : 'یک ابزار انتخاب کن. علامت‌ها به همین پوزیشن می‌چسبن و در مرور هم نمایش داده می‌شن.';
    bd2.style.touchAction = ANN.mode ? 'none' : '';
    btn.classList.toggle('on', !bar.hidden);
  }
  btn.onclick = function () { bar.hidden = !bar.hidden; if (bar.hidden) ANN.mode = null; sync(); };
  bar.onclick = function (e) {
    var m = e.target.dataset && e.target.dataset.m; if (!m) return;
    if (m === 'clr') {
      var n = curNode();
      if (n) { delete n.hl; delete n.ar; draw(E); toast('علامت‌های این پوزیشن پاک شد.'); }
      return;
    }
    ANN.mode = (ANN.mode === m) ? null : m; sync();
  };
  // هر بار ویرایش تازه باز می‌شود، ابزار خاموش شروع شود تا حرکت مهره‌ها قفل نماند
  var _openEdit = window.openEdit;
  window.openEdit = function () { ANN.mode = null; ANN.start = null; sync(); return _openEdit.apply(this, arguments); };

  /* ---------- داده: روی گره‌ی فعلی درخت ---------- */
  function curNode() { return (E && !E.an) ? E.node : null; }
  function toggleSq(sq, c) {
    var n = curNode(); if (!n) return;
    n.hl = n.hl || {};
    if (n.hl[sq] === c) delete n.hl[sq]; else n.hl[sq] = c;
    if (!Object.keys(n.hl).length) delete n.hl;
  }
  function toggleArrow(f, t, c) {
    var n = curNode(); if (!n || f === t) return;
    n.ar = n.ar || [];
    var i, hit = -1;
    for (i = 0; i < n.ar.length; i++) if (n.ar[i].f === f && n.ar[i].t === t) hit = i;
    if (hit > -1) { if (n.ar[hit].c === c) n.ar.splice(hit, 1); else n.ar[hit].c = c; }
    else n.ar.push({ f: f, t: t, c: c });
    if (!n.ar.length) delete n.ar;
  }

  /* ---------- نمایش (ویرایش و مرور) ---------- */
  function ensureSvg(k, bd) {
    var s = document.getElementById('an' + k);
    if (!s) {
      s = document.createElementNS(NS, 'svg');
      s.id = 'an' + k; s.setAttribute('viewBox', '0 0 80 80'); s.setAttribute('aria-hidden', 'true');
      s.style.cssText = 'position:absolute;pointer-events:none;z-index:3;display:none';
      bd.parentNode.appendChild(s);
    }
    return s;
  }
  function arrow(A, Bp, col, op) {
    var dx = Bp[0] - A[0], dy = Bp[1] - A[1], n = Math.sqrt(dx * dx + dy * dy) || 1, ux = dx / n, uy = dy / n, nx = -uy, ny = ux;
    var sw = 1.25, hw = 3.1, hl = 3.9, bx = Bp[0] - ux * hl, by = Bp[1] - uy * hl;
    var P = [[A[0] + nx * sw, A[1] + ny * sw], [bx + nx * sw, by + ny * sw], [bx + nx * hw, by + ny * hw], [Bp[0], Bp[1]], [bx - nx * hw, by - ny * hw], [bx - nx * sw, by - ny * sw], [A[0] - nx * sw, A[1] - ny * sw]];
    return '<polygon points="' + P.map(function (z) { return z[0].toFixed(2) + ',' + z[1].toFixed(2); }).join(' ') + '" fill="' + col + '" fill-opacity="' + op + '"/>';
  }
  function ptOf(sq, flip) { var f = F.indexOf(sq[0]), r = +sq[1]; return [((flip ? 7 - f : f) + .5) * 10, ((flip ? r - 1 : 8 - r) + .5) * 10]; }

  function draw(b) {
    if (!b || !b.el) return;
    var id = b.el.id, k = id === 'bd2' ? '2' : id === 'bd3' ? '3' : null; if (!k) return;
    Array.prototype.forEach.call(b.el.querySelectorAll('.sq'), function (s) { s.classList.remove('ang', 'anr'); });
    var svg = ensureSvg(k, b.el);
    var ok = (b === window.E) ? !b.an : (b === window.V ? !b.free : false);   // در تحلیل آزاد، پوزیشن همان گره‌ی درخت نیست
    var n = ok ? b.node : null;
    var h = '';
    if (n) {
      var flip = b.color === 'b';
      if (n.hl) Object.keys(n.hl).forEach(function (sq) {
        var el = b.el.querySelector('[data-s="' + sq + '"]'); if (el) el.classList.add(n.hl[sq] === 'r' ? 'anr' : 'ang');
      });
      (n.ar || []).forEach(function (a) { h += arrow(ptOf(a.f, flip), ptOf(a.t, flip), COL[a.c] || COL.g, .85); });
      if (k === '2' && ANN.start && ANN.cur && ANN.start !== ANN.cur && (ANN.mode === 'ag' || ANN.mode === 'ar'))
        h += arrow(ptOf(ANN.start, flip), ptOf(ANN.cur, flip), COL[ANN.mode === 'ar' ? 'r' : 'g'], .5);   // پیش‌نمایش هنگام کشیدن
    } else if (k === '2' && ANN.start && ANN.cur && ANN.start !== ANN.cur && E && !E.an && (ANN.mode === 'ag' || ANN.mode === 'ar')) {
      h += arrow(ptOf(ANN.start, E.color === 'b'), ptOf(ANN.cur, E.color === 'b'), COL[ANN.mode === 'ar' ? 'r' : 'g'], .5);
    }
    if (!h) { svg.style.display = 'none'; svg.innerHTML = ''; return; }
    svg.style.left = b.el.offsetLeft + 'px'; svg.style.top = b.el.offsetTop + 'px';
    svg.style.width = b.el.offsetWidth + 'px'; svg.style.height = b.el.offsetHeight + 'px';
    svg.innerHTML = h; svg.style.display = 'block';
  }

  var _render = window.render;
  window.render = function () {
    var r = _render.apply(this, arguments);
    try { if (window.B === window.E || window.B === window.V) draw(window.B); } catch (e) { console.error(e); }
    return r;
  };
  var _ea = window.engArrows;
  window.engArrows = function () {            // همان جاهایی که فلش انجین دوباره چیده می‌شود (چرخش صفحه، تمام‌صفحه)
    var r = _ea.apply(this, arguments);
    try { draw(window.E); draw(window.V); } catch (e) { }
    return r;
  };

  /* ---------- کشیدن روی صفحه‌ی ویرایش ---------- */
  function sqAt(x, y) {
    var el = document.elementFromPoint(x, y); el = el && el.closest && el.closest('.sq');
    return (el && el.parentNode === bd2) ? el.dataset.s : null;
  }
  bd2.addEventListener('pointerdown', function (e) {
    if (!ANN.mode || !E || E.an) return;
    e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation();
    ANN.start = sqAt(e.clientX, e.clientY); ANN.cur = ANN.start;
  }, true);
  bd2.addEventListener('click', function (e) {              // جلوگیری از انتخاب/حرکت مهره‌ی عادی در حالت ابزار
    if (ANN.mode && E && !E.an) { e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); }
  }, true);
  document.addEventListener('pointermove', function (e) {
    if (!ANN.start) return;
    var s = sqAt(e.clientX, e.clientY);
    if (s && s !== ANN.cur) { ANN.cur = s; draw(E); }
  }, true);
  document.addEventListener('pointerup', function (e) {
    if (!ANN.start) return;
    var from = ANN.start, to = sqAt(e.clientX, e.clientY) || ANN.cur;
    ANN.start = ANN.cur = null;
    if (from && to && E && !E.an) {
      if (ANN.mode === 'sg' || ANN.mode === 'sr') { if (from === to) toggleSq(from, ANN.mode === 'sr' ? 'r' : 'g'); }
      else if (from !== to) toggleArrow(from, to, ANN.mode === 'ar' ? 'r' : 'g');
    }
    draw(E);
  }, true);
  document.addEventListener('pointercancel', function () { if (ANN.start) { ANN.start = ANN.cur = null; draw(E); } }, true);
  window.addEventListener('resize', function () { try { draw(window.E); draw(window.V); } catch (e) { } });

  sync();
})();

/* LINER-UPDATE id="branch-preview-v2" title="پیش‌نمایش شاخه‌ها با صفحه‌ی شطرنج کنار هر لاین در دسته‌ها" base="v6" */
(function () {
  if (window.__BRANCH_PV1) { try { if (typeof toast === 'function') toast('نسخه‌ی v1 پیش‌نمایش شاخه‌ها را از آپدیت‌ها حذف کن و برنامه را بارگذاری مجدد کن.', 6000); } catch (e) {} return; }
  if (window.__BRANCH_PV2) return;
  window.__BRANCH_PV2 = 1;

  /* ---------- استایل ---------- */
  var st = document.createElement('style');
  st.id = 'lt-branch-pv-css';
  // اندازه‌ها صریح و مهره‌ها absolute تا مثل صفحه‌های خود اپ همیشه دیده شوند
  st.textContent =
    '.lpr{display:flex;align-items:center;gap:10px;flex:1 1 100%;min-width:0}' +
    '.lpr b{flex:1 1 auto!important;min-width:0}' +
    '.lpv{flex:none;position:relative;cursor:pointer;-webkit-tap-highlight-color:transparent}' +
    '.lpb{width:150px!important;height:150px!important;display:grid!important;grid-template-columns:repeat(8,18.75px)!important;grid-template-rows:repeat(8,18.75px)!important;direction:ltr;border-radius:6px;overflow:hidden}' +
    '.lpb>div{width:18.75px!important;height:18.75px!important;position:relative;box-sizing:border-box}' +
    '.lpb>div.l{background:var(--sl,#eeeed2)!important}.lpb>div.k{background:var(--sd,#769656)!important}' +
    '.lpb .pc{position:absolute!important;left:0;top:0;width:18.75px!important;height:18.75px!important;display:block;z-index:1;background-repeat:no-repeat;background-position:center;background-size:96%}' +
    '.lpv i{position:absolute;right:3px;bottom:3px;font:700 11px/1 system-ui,sans-serif;font-style:normal;padding:3px 5px;border-radius:6px;background:rgba(0,0,0,.65);color:#fff;direction:ltr}';
  document.head.appendChild(st);

  /* ---------- شاخه‌ها (برگ‌های درخت) و پوزیشن نهایی هر کدام ---------- */
  var cache = {};
  function leafPaths(l) {
    var out = [];
    (function go(n, path) {
      if (out.length >= 60) return;
      if (!n.c || !n.c.length) { out.push(path); return; }
      n.c.forEach(function (ch) { go(ch, path.concat(ch)); });
    })(l.tree || { c: [] }, []);
    return out;
  }
  function getLeaves(l) {
    var k = l.id + '|' + (l.ut || 0) + '|' + (typeof cnt === 'function' && l.tree ? cnt(l.tree) : 0);
    var c = cache[l.id];
    if (!c || c.k !== k) { c = cache[l.id] = { k: k, paths: leafPaths(l), fens: {} }; }
    return c;
  }
  function fenAt(l, c, i) {
    if (c.fens[i]) return c.fens[i];
    var g;
    try {
      g = newGame(l);
      c.paths[i].forEach(function (n) { g.move(n.san); });
    } catch (e) { try { g = newGame(l); } catch (x) { return ''; } }
    return (c.fens[i] = g.fen());
  }
  function boardHtml(fen, flip) {
    var pl = plc(fen), h = '', i, j, f, r, p, c;
    for (j = 0; j < 64; j++) {
      i = flip ? 63 - j : j;
      f = i % 8; r = i >> 3; p = pl[i];
      c = 'ms ' + ((f + r) % 2 === 0 ? 'l' : 'k');
      h += '<div class="' + c + '">' + (p ? '<span class="pc ' + (p === p.toUpperCase() ? 'w' : 'b') + p.toUpperCase() + '"></span>' : '') + '</div>';
    }
    return h;
  }
  function badge(i, n) { return n > 1 ? '<i>' + (i + 1) + '/' + n + '</i>' : ''; }

  /* ---------- اضافه کردن صفحه به ردیف هر لاین ---------- */
  var orig = window.rowHtml;
  window.rowHtml = function (l) {
    var h = orig(l);
    try {
      var c = getLeaves(l), fen = fenAt(l, c, 0);
      if (!fen) return h;
      var box = '<div class="lpv" data-lid="' + l.id + '" data-i="0" title="برای دیدن شاخه‌ی بعدی بزن">' +
        '<div class="lpb">' + boardHtml(fen, l.side === 'b') + '</div>' + badge(0, c.paths.length) + '</div>';
      var a = h.indexOf('<div class="row"><b>');
      var b = h.indexOf('</small></b><button');
      if (a < 0 || b < 0) return h;
      return h.slice(0, a) + '<div class="row"><div class="lpr">' + box + '<b>' + h.slice(a + 20, b) + '</small></b></div>' + h.slice(b + 11);
    } catch (e) { return h; }
  };

  /* ---------- لمس صفحه = شاخه‌ی بعدی ---------- */
  document.addEventListener('click', function (e) {
    var v = e.target.closest && e.target.closest('.lpv');
    if (!v) return;
    e.stopPropagation(); e.preventDefault();
    try {
      var l = S.lines.filter(function (x) { return String(x.id) === v.getAttribute('data-lid'); })[0];
      if (!l) return;
      var c = getLeaves(l), n = c.paths.length;
      var i = (+v.getAttribute('data-i') + 1) % n;
      var fen = fenAt(l, c, i); if (!fen) return;
      v.setAttribute('data-i', i);
      v.innerHTML = '<div class="lpb">' + boardHtml(fen, l.side === 'b') + '</div>' + badge(i, n);
    } catch (x) {}
  }, true);

  try { if (typeof renderLib === 'function') renderLib(); } catch (e) {}
  console.log('[branch-preview-v2] ✓ loaded');
})();

/* LINER-UPDATE id="bulk-fen-import" title="افزودن گروهی FEN" base="v6" */
/*
  افزودن گروهی FEN:
  - هر خط یک FEN کامل (۴ تا ۶ فیلد؛ ۴ و ۵ فیلدی خودکار تکمیل می‌شود)
  - نام هر FEN: رشته‌ی تصادفی ۱۰ حرفی یکتا (نسبت به همه‌ی لاین‌های موجود)
  - وزیر روی تخته (Q/q) → دسته‌ی «وسط بازی» · بدون وزیر → «آخر بازی»
  - دسته‌ی جدید ساخته نمی‌شود؛ از دسته‌های موجود استفاده می‌شود
  - حداکثر ۵۰ پوزیشن در هر بار
  - پیش‌نمایش زنده با مینی‌تخته قبل از ثبت
*/
(function(){
  if(window.__bulkFen) return;
  if(typeof window.Chess !== 'function'){ console.error('[bulk-fen] Chess missing'); return; }
  if(!window.S || !Array.isArray(window.S.lines)){ console.error('[bulk-fen] S missing'); return; }

  var MID = 'وسط بازی';
  var END = 'آخر بازی';
  var NAME_LEN = 10;
  /* حروف مشابه (0/O, 1/l/I) حذف شدن تا نام‌ها خواناتر باشن */
  var NAME_CHARS = 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';

  /* ---------- helpers ---------- */
  function esc(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
  function faN(n){ return String(n).replace(/[0-9]/g, function(d){ return '۰۱۲۳۴۵۶۷۸۹'[+d]; }); }
  function normalizeFen(fen){
    var parts = fen.split(/\s+/);
    if(parts.length === 4) return fen + ' 0 1';
    if(parts.length === 5) return fen + ' 1';
    return fen;
  }
  function hasQueen(fen){ return /[Qq]/.test(fen.split(' ')[0]); }
  function catOf(fen){ return hasQueen(fen) ? MID : END; }
  function sideOf(fen){ return fen.split(' ')[1] === 'b' ? 'سیاه' : 'سفید'; }
  function countPieces(fen){
    var p = fen.split(' ')[0], n = 0;
    for(var i = 0; i < p.length; i++){
      var c = p[i];
      if(c !== '/' && !(c >= '1' && c <= '8')) n++;
    }
    return n;
  }
  function randName(){
    var s = '';
    for(var i = 0; i < NAME_LEN; i++) s += NAME_CHARS.charAt(Math.floor(Math.random() * NAME_CHARS.length));
    return s;
  }
  function buildUsedNames(){
    var u = Object.create(null);
    (window.S.lines || []).forEach(function(l){
      if(l && l.name) u[String(l.name).toLowerCase()] = 1;
    });
    return u;
  }
  function uniqueName(used){
    for(var t = 0; t < 10000; t++){
      var n = randName();
      if(!used[n.toLowerCase()]){
        used[n.toLowerCase()] = 1;
        return n;
      }
    }
    /* احتمالاً هیچ‌وقت به اینجا نمی‌رسیم، ولی برای اطمینان: */
    var n2;
    do { n2 = randName() + Math.random().toString(36).slice(2, 4); } while(used[n2.toLowerCase()]);
    used[n2.toLowerCase()] = 1;
    return n2;
  }
  function miniBoardHtml(fen, size){
    var pl;
    try { pl = window.plc(fen); } catch(e) { return ''; }
    if(!pl || pl.length < 64) return '';
    var h = '';
    for(var i = 0; i < 64; i++){
      var f = i % 8, r = i >> 3;
      var light = (f + r) % 2 === 0;
      var p = pl[i];
      h += '<div style="background:' + (light ? 'var(--sl)' : 'var(--sd)') + ';position:relative;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0">'
        + (p ? '<span class="pc ' + (p === p.toUpperCase() ? 'w' : 'b') + p.toUpperCase() + '" style="width:100%;height:100%"></span>' : '')
        + '</div>';
    }
    return '<div style="display:grid;grid-template-columns:repeat(8,1fr);grid-template-rows:repeat(8,1fr);direction:ltr;width:' + size + 'px;height:' + size + 'px;border-radius:5px;overflow:hidden;box-shadow:0 0 0 1px var(--ln);flex:0 0 auto">' + h + '</div>';
  }

  /* ---------- UI ---------- */
  var addBox = document.getElementById('addbox');
  if(!addBox){ console.error('[bulk-fen] addbox missing'); return; }
  if(document.getElementById('bulkbox')){ window.__bulkFen = true; return; }

  addBox.insertAdjacentHTML('afterend',
    '<details id="bulkbox" class="own" style="margin-top:12px">'
    + '<summary>افزودن گروهی FEN (تا ۵۰ پوزیشن)</summary>'
    + '<p class="meta">هر خط یک FEN. برای هر کدام یک نام تصادفی ۱۰ حرفی یکتا ساخته می‌شود. وزیر روی تخته → «وسط بازی» · بدون وزیر → «آخر بازی». FEN ۴ یا ۵ فیلدی خودکار کامل می‌شود.</p>'
    + '<label for="bfen">FENها (هر خط یکی)</label>'
    + '<textarea id="bfen" class="l" placeholder="8/8/4k3/8/4K3/4P3/8/8 w - - 0 1&#10;r1bqkbnr/pppp1ppp/2n5/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 2 3&#10;..."></textarea>'
    + '<div class="msg" id="bmsg"></div>'
    + '<div id="bprev" style="max-height:340px;overflow-y:auto;margin:10px 0"></div>'
    + '<div class="bar"><button class="p" id="badd" type="button" disabled>ثبت همه</button><button id="bclr" type="button">پاک کردن</button></div>'
    + '</details>'
  );

  /* ---------- parse & preview ---------- */
  function parseAndPreview(){
    var raw = document.getElementById('bfen').value;
    var msg = document.getElementById('bmsg');
    var prev = document.getElementById('bprev');
    var btn = document.getElementById('badd');

    var lines = raw.split(/\r?\n/)
      .map(function(l){ return l.trim().replace(/^["']|["']$/g, ''); })
      .filter(Boolean);

    if(!lines.length){
      prev.innerHTML = '<p class="meta" style="text-align:center;padding:24px 0;color:var(--mut)">هنوز FENی وارد نکردی.</p>';
      msg.textContent = '';
      btn.disabled = true;
      btn.textContent = 'ثبت همه';
      return { items: [], validCount: 0 };
    }

    var truncated = false;
    if(lines.length > 50){ truncated = true; lines = lines.slice(0, 50); }

    var g = new window.Chess();
    var used = buildUsedNames();
    var items = [], validCount = 0, invalidCount = 0, midCount = 0, endCount = 0;

    lines.forEach(function(raw, idx){
      var fen = normalizeFen(raw);
      var v = g.validate_fen(fen);
      if(v.valid){
        var cat = catOf(fen);
        var name = uniqueName(used);
        items.push({ fen: fen, cat: cat, name: name, valid: true, pieces: countPieces(fen), side: sideOf(fen) });
        validCount++;
        if(cat === MID) midCount++; else endCount++;
      } else {
        items.push({ fen: raw, valid: false, error: v.error, index: idx + 1 });
        invalidCount++;
      }
    });

    var h = '';
    items.forEach(function(item){
      if(!item.valid){
        h += '<div style="display:flex;align-items:center;gap:10px;background:rgba(255,107,98,.07);border:1px solid var(--bad);border-radius:10px;padding:8px 12px;margin:0 0 6px">'
          + '<div style="flex:1;min-width:0;font-weight:600;color:var(--bad)">خط ' + faN(item.index) + ': FEN نامعتبر'
          + '<small style="display:block;color:var(--mut);font-weight:400;font-size:.82em;direction:ltr;text-align:left;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(item.fen) + '</small></div>'
          + '</div>';
      } else {
        var catColor = item.cat === MID ? 'var(--acc)' : '#b45309';
        h += '<div style="display:flex;align-items:center;gap:12px;background:var(--card);border:1px solid var(--ln);border-radius:10px;padding:8px 12px;margin:0 0 6px">'
          + miniBoardHtml(item.fen, 56)
          + '<div style="flex:1;min-width:0;font-weight:600">' + esc(item.name)
          + '<small style="display:block;color:var(--mut);font-weight:400;font-size:.85em;margin-top:3px">'
          + '<span style="color:' + catColor + ';font-weight:700">' + item.cat + '</span>'
          + ' · ' + faN(item.pieces) + ' مهره'
          + ' · نوبت ' + item.side
          + '</small></div>'
          + '</div>';
      }
    });
    prev.innerHTML = h;

    var msgs = [];
    if(truncated) msgs.push('بیشتر از ۵۰ خط بود؛ ۵۰ تای اول استفاده می‌شود.');
    if(invalidCount > 0) msgs.push(faN(invalidCount) + ' خط نامعتبر (نادیده گرفته می‌شود).');
    if(validCount > 0) msgs.push(faN(validCount) + ' معتبر: ' + faN(midCount) + ' وسط بازی، ' + faN(endCount) + ' آخر بازی.');
    msg.textContent = msgs.join(' ');
    msg.style.color = invalidCount > 0 ? 'var(--bad)' : 'var(--acc)';

    btn.disabled = validCount === 0;
    btn.textContent = validCount > 0 ? ('ثبت ' + faN(validCount) + ' پوزیشن') : 'ثبت همه';

    return { items: items, validCount: validCount };
  }

  /* ---------- submit ---------- */
  function submitAll(){
    var result = parseAndPreview();
    if(result.validCount === 0) return;

    var validItems = result.items.filter(function(i){ return i.valid; });
    var now = Date.now();
    var newLines = [];

    validItems.forEach(function(item, idx){
      var id = now.toString(36) + Math.random().toString(36).slice(2, 6) + idx.toString(36);
      newLines.push({
        id: id,
        name: item.name,
        cat: item.cat,
        side: 'both',
        fen: item.fen,
        tree: { c: [] },
        errs: 0,
        ut: now
      });
    });

    newLines.forEach(function(l){ window.S.lines.push(l); });

    if(typeof window.byId === 'function'){
      newLines.forEach(function(l){
        var stored = window.byId(l.id);
        if(stored) stored.ts = Date.now();
      });
    }

    if(typeof window.save === 'function') window.save();
    if(window.dirty && typeof window.dirty === 'object'){
      newLines.forEach(function(l){ window.dirty[l.id] = 1; });
    }
    if(typeof window.sched === 'function') window.sched();
    if(typeof window.ghSched === 'function') window.ghSched();

    var midAdded = newLines.filter(function(l){ return l.cat === MID; }).length;
    var endAdded = newLines.filter(function(l){ return l.cat === END; }).length;

    document.getElementById('bfen').value = '';
    document.getElementById('bprev').innerHTML = '<p class="meta" style="text-align:center;padding:24px 0;color:var(--acc);font-weight:600">✓ ' + faN(newLines.length) + ' پوزیشن ثبت شد.</p>';
    document.getElementById('bmsg').textContent = '';
    document.getElementById('badd').disabled = true;
    document.getElementById('badd').textContent = 'ثبت همه';

    if(window.UI && typeof window.UI === 'object'){
      window.UI.open = true;
      window.UI.cat = midAdded >= endAdded ? MID : END;
    }

    if(typeof window.renderLib === 'function') window.renderLib();

    if(typeof window.toast === 'function'){
      window.toast('✓ ' + faN(newLines.length) + ' پوزیشن ثبت شد (' + faN(midAdded) + ' وسط بازی، ' + faN(endAdded) + ' آخر بازی)', 5000);
    }
  }

  /* ---------- bind ---------- */
  document.getElementById('bfen').addEventListener('input', parseAndPreview);
  document.getElementById('badd').addEventListener('click', submitAll);
  document.getElementById('bclr').addEventListener('click', function(){
    document.getElementById('bfen').value = '';
    parseAndPreview();
  });

  window.__bulkFen = true;
  console.log('[bulk-fen] نصب شد. دسته‌ها: وسط بازی / آخر بازی · نام‌ها: ۱۰ حرفی یکتا');

  try{
    if(!localStorage.getItem('lt_bulkfen_v3_installed')){
      localStorage.setItem('lt_bulkfen_v3_installed', '1');
      if(typeof window.toast === 'function')
        toast('✓ «افزودن گروهی FEN» نصب شد (نسخه‌ی ۳)', 4000);
    }
  }catch(e){}
})();

/* LINER-UPDATE id="capture-fx-arrow-labels-v1" title="انیمیشن خورد شدن مهره‌ی کپچرشده + شماره‌ی خط انجین روی فلش‌ها" base="v6" */
(function () {
  if (window.__LINER_FXAL) return;
  window.__LINER_FXAL = 1;

  /* ================= 1) شماره‌ی خط انجین نزدیک نوک فلش ================= */
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  var TIP_GAP = 0.8;   // فاصله‌ی مرکز عدد از نوک فلش (واحد: ۱/۱۰ خانه)؛ کمتر = عدد بیشتر روی فلش می‌شینه
