    });

    // جرقه‌ی برخورد + حلقه‌ی ضربه
    var ring = document.createElement('div');
    ring.style.cssText = 'position:absolute;left:50%;top:50%;width:' + W * .9 + 'px;height:' + W * .9 + 'px;margin:' + (-W * .45) + 'px 0 0 ' + (-W * .45) + 'px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.85) 0%,rgba(255,214,102,.55) 38%,rgba(255,214,102,0) 70%);opacity:0';
    box.appendChild(ring);
    var sparks = [];
    for (var k = 0; k < 9; k++) {
      var sp = document.createElement('div'), sz = rnd(.06, .12) * W, ang = rnd(0, Math.PI * 2), dist = rnd(.5, 1.3) * W;
      sp.style.cssText = 'position:absolute;left:50%;top:50%;width:' + sz + 'px;height:' + sz + 'px;margin:' + (-sz / 2) + 'px 0 0 ' + (-sz / 2) + 'px;border-radius:50%;background:' + (k % 2 ? '#ffd666' : '#fff') + ';opacity:0';
      box.appendChild(sp);
      sparks.push([sp, Math.cos(ang) * dist, Math.sin(ang) * dist]);
    }
    document.body.appendChild(box);

    parts.forEach(function (p) {
      p[0].animate([
        { transform: 'translate(0,0) rotate(0deg) scale(1)', opacity: 1, offset: 0 },
        { transform: 'translate(' + p[1] * .35 + 'px,' + p[2] * .2 + 'px) rotate(' + p[3] * .3 + 'deg) scale(1)', opacity: 1, offset: .25 },
        { transform: 'translate(' + p[1] + 'px,' + p[2] + 'px) rotate(' + p[3] + 'deg) scale(.55)', opacity: 0, offset: 1 }
      ], { duration: p[4], delay: DELAY, easing: 'cubic-bezier(.2,.7,.3,1)', fill: 'both' });
    });
    ring.animate([{ transform: 'scale(.3)', opacity: .95 }, { transform: 'scale(1.7)', opacity: 0 }],
      { duration: 360, delay: DELAY, easing: 'ease-out', fill: 'both' });
    sparks.forEach(function (s) {
      s[0].animate([{ transform: 'translate(0,0) scale(1)', opacity: 1 }, { transform: 'translate(' + s[1] + 'px,' + s[2] + 'px) scale(.2)', opacity: 0 }],
        { duration: rnd(380, 560), delay: DELAY, easing: 'cubic-bezier(.1,.7,.3,1)', fill: 'both' });
    });
    setTimeout(function () { if (box.parentNode) box.parentNode.removeChild(box); }, DELAY + 1000);
  }

  var REDUCED = function () { return !!(window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches); };

  var _anim = window.anim;
  window.anim = function (m, el) {
