    } catch (e) { console.error(e); }
    return r;
  };

  /* ================= 3) کیش و مات: لرزش شاه در کیش، واژگون شدن شاه در مات ================= */
  function findKing(g, col) {
    var bd = g.board(), r, c, p;
    for (r = 0; r < 8; r++) for (c = 0; c < 8; c++) { p = bd[r][c]; if (p && p.type === 'k' && p.color === col) return 'abcdefgh'[c] + (8 - r); }
