      var sqEl = sq && b.el.querySelector('[data-s="' + sq + '"]'), pc = sqEl && sqEl.querySelector('.pc');
      if (!pc) return r;
      var play = !!mv && !jp && !!pc.animate && !REDUCED(), delay = drag ? 0 : 230;
      var dir = ((sq.charCodeAt(0) + sq.charCodeAt(1)) % 2) ? 1 : -1;   // جهت افتادن برای هر خانه ثابت است
      if (mate) {
        var rest = 'translateY(11%) rotate(' + (dir * 92) + 'deg)';
        pc.style.transformOrigin = '50% 55%';
        pc.style.transform = rest;                                       // شاه مات‌شده تا عوض شدن صفحه، خوابیده می‌ماند
        if (play) {
          pc.animate([
            { transform: 'translateY(0) rotate(0deg)', offset: 0 },
            { transform: 'translateY(0) rotate(' + (-dir * 7) + 'deg)', offset: .22 },
            { transform: 'translateY(8%) rotate(' + (dir * 100) + 'deg)', offset: .62 },
