        ], { duration: 520, delay: delay, easing: 'ease-in-out' });
        ring(sqEl, 'rgba(255,170,0,.7)', delay);
      }
    } catch (e) { console.error(e); }
    return r;
  };
})();

/* LINER-UPDATE id="cat-template-v1" title="دسته‌ی الگو (شروع/وسط/آخر بازی/مات) + انتخاب بازه‌ی لاین‌ها برای تمرین و مرور" base="v6" */
(function () {
  if (window.__LINER_TPL) return;
  window.__LINER_TPL = 1;

  var GRP = 'الگو', PFX = GRP + ' › ';
  var A = PFX + 'شروع بازی', M = PFX + 'وسط بازی', Z = PFX + 'آخر بازی', T = PFX + 'مات';
  var SECS = [A, M, Z, T];

  function tp(fn, a, b) { try { LU.patch(fn, a, b); } catch (e) { console.error('patch ' + fn, e); } }
  function inGrp(c) { return !!c && c.indexOf(PFX) === 0; }

  /* ================= 1) دسته‌ها: فقط «الگو» با سه بخش ================= */
  CATS.splice(0, CATS.length, A, M, Z, T);   // «شروع بازی»‌ی قبلی برداشته شد

  var MAP = {};
  ['شروع بازی', 'الگو', 'اوپنینگ', 'اپنینگ', 'opening', 'Opening'].forEach(function (k) { MAP[k] = A; });
  ['وسط بازی', 'میان بازی', 'میانه بازی', 'میدل گیم', 'middlegame', 'Middlegame'].forEach(function (k) { MAP[k] = M; });
  ['آخر بازی', 'اندگیم', 'endgame', 'Endgame'].forEach(function (k) { MAP[k] = Z; });
  ['مات', 'checkmate', 'Checkmate', 'mate', 'Mate'].forEach(function (k) { MAP[k] = T; });
  window.ncat = function (c) { return MAP[c] || c; };

  // لاین‌های قدیمی («شروع بازی»، «آخر بازی»، «الگو») به بخش‌های جدید منتقل می‌شن؛ چیزی حذف نمی‌شه
  var moved = [];
