    CFG.band=Math.round(pn('gmband',.8,0,20)*100)/100;CFG.thr=Math.round(pn('gmthr',.8,0,20)*100)/100;
    CFG.rl=Math.round(pn('gmrl',5,1,10));CFG.rt=Math.round(pn('gmrt',1,1,3));CFG.spd=Math.round(pn('gmspd',1100,300,4000));CFG.tc=g$('gmtc').value||'off';
    try{localStorage.setItem(LS,JSON.stringify(CFG))}catch(e){}
