  ['gmdep','gmn','gmband','gmthr','gmrl','gmrt','gmspd','gmtc'].forEach(function(id){g$(id).onchange=gmCfgRead});

  /* ---------- چیدن پوزیشن (مثل ادیتور لاین) ---------- */
  function gmSetup(fn){if(!GM||GM.mode!=='setup')return;fn();gmR();gmUi()}
  g$('gmf').onclick=function(){
    gmSetup(function(){
      if(GM.ply>=GM.hist.length)return;
      var h=GM.hist[GM.ply],m=GM.g.move({from:h.from,to:h.to,promotion:h.promotion});
      if(!m)return;GM.ply++;GM.last=[m.from,m.to];GM.sel=null;
    });
  };
  g$('gmb').onclick=function(){
    gmSetup(function(){if(GM.ply<=0)return;GM.ply--;gmBuild()});
