  g$('gmflip').onclick=function(){gmSetup(function(){GM.color=GM.color==='w'?'b':'w'})};
  g$('gmdel').onclick=function(){gmSetup(function(){if(GM.ply<=0)return;GM.ply--;GM.hist.length=GM.ply;gmBuild()})};
  g$('gml').onclick=function(e){
    var k=e.target.dataset&&e.target.dataset.k;if(k==null||!GM||GM.mode!=='setup')return;
    gmSetup(function(){GM.ply=Math.max(0,Math.min(GM.hist.length,+k));gmBuild()});
  };
  g$('gmfenb').onclick=function(){
    var f=g$('gmfen').value.trim(),m=g$('gmm');m.style.color='';m.textContent='';
    if(f&&!new Chess().validate_fen(f).valid){m.textContent='FEN معتبر نیست.';return}
    gmSetup(function(){GM.sfen=f||null;GM.hist=[];GM.ply=0;gmBuild()});
    m.style.color='var(--acc)';m.textContent='پوزیشن شروع تنظیم شد.';
  };
  g$('gmpgnb').onclick=function(){
    var txt=g$('gmpgn').value,m=g$('gmm');m.style.color='';m.textContent='';
    try{
      var hf=txt.match(/\[FEN\s+"([^"]+)"\]/i),fen=hf?hf[1]:(GM.sfen||null);
      if(fen&&!new Chess().validate_fen(fen).valid)throw new Error('FEN معتبر نیست.');
      var body=txt.replace(/\[[^\]]*\]/g,' ').replace(/\{[^}]*\}/g,' ').replace(/;[^\n]*/g,' '),prev;
      do{prev=body;body=body.replace(/\([^()]*\)/g,' ')}while(body!==prev);
      body=body.replace(/\$\d+/g,' ').replace(/\d+\s*\.(\s*\.\.)?/g,' ');
      var tk=body.split(/\s+/).filter(function(x){return x&&!/^(1-0|0-1|1\/2-1\/2|\*)$/.test(x)});
      var g=fen?new Chess(fen):new Chess(),hist=[];
      tk.forEach(function(x){
        x=x.replace(/[!?]+$/,'');var mv=g.move(x,{sloppy:true});
        if(!mv)throw new Error('حرکت نامعتبر: '+x);
        hist.push({from:mv.from,to:mv.to,promotion:mv.promotion,san:mv.san});
      });
      if(!hist.length)throw new Error('حرکتی پیدا نشد.');
      gmSetup(function(){GM.sfen=fen;GM.hist=hist;GM.ply=hist.length;gmBuild()});
      g$('gmfen').value=fen||'';
      m.style.color='var(--acc)';m.textContent='پوزیشن چیده شد ('+hist.length+' نیم‌حرکت).';
    }catch(e){m.textContent='خطا: '+e.message}
  };

  /* ---------- ورودی تخته: کلیک و کشیدن ---------- */
  var bd=g$('bdg'),DD=null,gdr=false;
  function gmTap(sq){
    if(!gmCan())return;
    var g=GM.g,pc=g.get(sq);
    if(GM.sel&&GM.sel!==sq){
      var cand=g.moves({verbose:true}).filter(function(m){return m.from===GM.sel&&m.to===sq});
      if(cand.length){gmMove(cand);return}
    }
    GM.sel=(pc&&pc.color===g.turn()&&GM.sel!==sq&&(GM.mode==='setup'||pc.color===GM.color))?sq:null;
    gmR();
  }
  function gmMove(cand){
    var ok=cand.filter(function(m){return !m.promotion||m.promotion==='q'})[0]||cand[0];
    if(GM.mode==='setup'){
      GM.hist.length=GM.ply;
      var mm=GM.g.move({from:ok.from,to:ok.to,promotion:ok.promotion});
      if(!mm)return;
      gmPush(mm);GM.last=[mm.from,mm.to];GM.sel=null;gmR(mm);gmUi();return;
    }
    gmUserMove(ok);
  }
  bd.addEventListener('click',function(e){
    if(gdr){gdr=false;return}
    var t=e.target.closest('.sq');if(!t)return;
    gmTap(t.dataset.s);
  });
  bd.addEventListener('pointerdown',function(e){
    if(e.button>0||!gmCan())return;
    var t=e.target.closest('.sq');if(!t)return;
    var sq=t.dataset.s,pc=GM.g.get(sq),pe=t.querySelector('.pc');
    if(!pc||pc.color!==GM.g.turn()||!pe)return;
    if(GM.mode==='play'&&pc.color!==GM.color)return;
    var sw=t.getBoundingClientRect().width,w=sw*1.15,gh=pe.cloneNode(false),seen={},tg=[];
    GM.g.moves({square:sq,verbose:true}).forEach(function(m){
      if(seen[m.to])return;seen[m.to]=1;
      var r=GM.el.querySelector('[data-s="'+m.to+'"]').getBoundingClientRect();
      tg.push({sq:m.to,x:r.left+r.width/2,y:r.top+r.height/2});
    });
    gh.style.cssText='position:fixed;z-index:60;pointer-events:none;margin:0;width:'+w+'px;height:'+w+'px';
    document.body.appendChild(gh);document.body.classList.add('dragging');
    pe.style.visibility='hidden';t.classList.add('sel');
    DD={b:GM,sq:sq,se:t,pe:pe,gh:gh,w:w,sw:sw,tg:tg,hs:null,x:e.clientX,y:e.clientY,moved:false,off:e.pointerType==='touch'?w*.55:0};
    ddMove(e);
  });
  function ddMove(e){
    if(!DD)return;
    if(Math.abs(e.clientX-DD.x)+Math.abs(e.clientY-DD.y)>6)DD.moved=true;
    var y=e.clientY-DD.off;
    DD.gh.style.left=(e.clientX-DD.w/2)+'px';DD.gh.style.top=(y-DD.w/2)+'px';
    if(!DD.moved)return;
    var h=snapT(DD,e.clientX,y);
    if(h!==DD.hs){
      var o=DD.hs&&GM.el.querySelector('[data-s="'+DD.hs+'"]');if(o)o.classList.remove('hov');
      var n=h&&GM.el.querySelector('[data-s="'+h+'"]');if(n)n.classList.add('hov');
      DD.hs=h;
    }
  }
  document.addEventListener('pointermove',ddMove);
  document.addEventListener('pointerup',function(e){
    if(!DD)return;
    var d=DD;DD=null;document.body.classList.remove('dragging');d.gh.remove();
    if(!d.moved){d.pe.style.visibility='';d.se.classList.remove('sel');return}
    gdr=true;setTimeout(function(){gdr=false},120);
    var to=snapT(d,e.clientX,e.clientY-d.off);
    GM.sel=d.sq;
    if(to&&to!==d.sq){window.noAnim=true;gmTap(to);window.noAnim=false}
    else gmR();
  });
  document.addEventListener('pointercancel',function(){
    if(!DD)return;
    var d=DD;DD=null;document.body.classList.remove('dragging');d.gh.remove();
    d.pe.style.visibility='';d.se.classList.remove('sel');
    var o=d.hs&&GM.el.querySelector('[data-s="'+d.hs+'"]');if(o)o.classList.remove('hov');
  });

  /* ---------- جریان بازی ---------- */
  function gmStartGame(){
    if(!GM||GM.mode!=='setup')return;
    if(!ENG_SRC.full){toast('اول فایل‌های انجین (js و wasm) رو از بخش «انجین ستاک‌فیش» انتخاب کن.');return}
    if((window.SA&&SA.run)||(window.CV&&CV.run)){toast('اول تحلیل مشابه / اشتراک اوپنینگ‌ها رو تموم کن.');return}
    if(GM.g.game_over()){toast('این پوزیشن تموم شده؛ بازی‌ای نداره.');return}
    gmCfgRead();
    GM.base={hist:GM.hist.slice(),ply:GM.ply,sfen:GM.sfen,color:GM.color};
    GM.hist.length=GM.ply;
    GM.mode='play';GM.tk++;GM.busy=false;GM.rv=false;GM.skip=false;GM.err=false;GM.rt=null;GM.sel=null;GM.hint=null;GM.wrong=null;GM.ty=null;GM.lastLb=null;
    GM.st={mis:0,shown:0,moves:0};GM.note='';
    GM.br=[];GM.curRec=null;GM.vfy=false;GM.result='';GM.pre=null;GM.psel=null;g$('gmendp').hidden=true;
    gmClkInit();
    gmUi();gmR();gmNext();
  }
  function gmNext(){
    if(!GM||GM.mode!=='play')return;
    var g=GM.g;
    gmMl();
    if(g.game_over()){gmEnd();return}
    if(g.turn()===GM.color){
      GM.busy=false;GM.err=false;gmUi();
      gmSt((GM.note?GM.note+'\n':'')+'نوبت توئه.');GM.note='';
      geEval(g.fen(),8,CFG.dep,function(){}); /* تحلیل پیش‌دستانه تا بعد از حرکتت سریع بررسی بشه */
      gpExec();
    }else gmEng();
  }
  function gmErr(err){
    if(!GM)return;
    GM.busy=false;GM.vfy=false;GM.err=GM.g.turn()!==GM.color;
    gmUi();gmSt('⚠ '+(err||'مشکلی در انجین پیش اومد.')+(GM.err?'':'\nدوباره حرکتت رو بزن.'));
  }
  function gmEng(){
    var tk=GM.tk;GM.busy=true;GM.err=false;GM.sel=null;gmUi();
    gmSt((GM.note?GM.note+'\n':'')+'انجین فکر می‌کنه...');GM.note='';
    var fen=GM.g.fen();
    geEval(fen,8,CFG.dep,function(L,err){
      if(tk!==GM.tk)return;
      if(!L||!L[1]){gmErr(err);return}
      var ks=skeys(L);
      if(!ks.length){gmErr('انجین حرکتی پیشنهاد نداد.');return}
      var best=cpv(L[ks[0]]),band=Math.round(CFG.band*100);
      var pool=ks.filter(function(i){return i<=CFG.n&&best-cpv(L[i])<=band});
      if(!pool.length)pool=[ks[0]];
      var pk=pool[Math.floor(Math.random()*pool.length)],u=L[pk].pv[0];
      setTimeout(function(){
        if(tk!==GM.tk)return;
        var m=GM.g.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]});
        if(!m){gmErr('حرکت انجین نامعتبر بود.');return}
        gmPush(m);GM.last=[m.from,m.to];GM.lastLb=null;GM.ty=null;GM.sel=null;
        if(GM.clk)GM.ce+=GM.cinc;
        GM.note='انجین '+m.san+' زد (یکی از '+pool.length+' گزینه‌ی قابل‌قبول).';
        gmR(m);gmNext();
      },380);
    });
  }
  function gmRevert(){
    GM.g.undo();GM.hist.pop();GM.ply=GM.hist.length;
    var h=GM.hist[GM.ply-1];GM.last=h?[h.from,h.to]:null;GM.lastLb=null;GM.ty=null;GM.sel=null;GM.busy=false;
  }
  function gmUserMove(ok){
    var tk=GM.tk,g=GM.g,Fp=g.fen();
    var mm=g.move({from:ok.from,to:ok.to,promotion:ok.promotion});
    if(!mm)return;
    var Fa=g.fen(),uci=mm.from+mm.to+(mm.promotion||'');
    gmPush(mm);GM.last=[mm.from,mm.to];GM.lastLb=null;GM.ty=null;GM.sel=null;GM.hint=null;GM.wrong=null;GM.busy=true;GM.vfy=true;GM.st.moves++;
    gmR(mm);gmUi();gmSt('در حال بررسی حرکتت...');
    if(g.in_checkmate()){GM.rt=null;GM.vfy=false;gmNext();return}
    geEval(Fp,8,CFG.dep,function(P,err){
      if(tk!==GM.tk)return;
      if(!P||!P[1]){GM.vfy=false;gmRevert();gmR();gmUi();gmErr(err);return}
      var ks=skeys(P),best=cpv(P[ks[0]]),hit=0;
      ks.forEach(function(i){if(!hit&&P[i].pv[0]===uci)hit=i});
      if(hit){gmVerdict(Fp,Fa,mm,P,best,cpv(P[hit]));return}
      var g2=new Chess(Fa);
      if(g2.game_over()){gmVerdict(Fp,Fa,mm,P,best,g2.in_checkmate()?10000:0);return}
      geEval(Fa,1,Math.max(1,CFG.dep-1),function(C,err2){
        if(tk!==GM.tk)return;
        if(!C||!C[1]){GM.vfy=false;gmRevert();gmR();gmUi();gmErr(err2);return}
        gmVerdict(Fp,Fa,mm,P,best,-cpv(C[1]));
      });
    });
  }
  function gmVerdict(Fp,Fa,mm,P,best,ev){
    var tk=GM.tk,loss=best-ev,thr=Math.round(CFG.thr*100);
    GM.vfy=false;
    if(loss<=thr){
      var was=!!GM.rt;GM.rt=null;
      if(GM.clk)GM.cm+=GM.cinc;
      if(was){GM.ty='f';GM.note='✓ آفرین، حرکت درست رو پیدا کردی.'}
      gmR();gmNext();return;
    }
    if(!GM.rt){
      GM.rt={fen:Fp,tries:0};GM.st.mis++;
      gmReview(Fp,Fa,mm,best,ev,loss);return;
    }
    GM.rt.tries++;
    gmRevert();
    if(GM.rt.tries>=CFG.rt){gmReveal(Fp,P);return}
    var left=CFG.rt-GM.rt.tries;
    GM.wrong=mm.to;gmR();gmUi();
    setTimeout(function(){if(tk===GM.tk&&GM.wrong){GM.wrong=null;gmR()}},500);
    gmSt('✗ '+mm.san+' هم درست نیست ('+fmt(ev)+' از دید تو، بهترین '+fmt(best)+').\nدوباره تلاش کن ('+left+' فرصت دیگه).');
  }
  function gmSl(ms,tk){
    return new Promise(function(res){
      var t=0;
      (function step(){
        if(tk!==GM.tk)return res(false);
        if(GM.skip||t>=ms)return res(true);
        t+=100;setTimeout(step,100);
      })();
    });
  }
  async function gmReview(Fp,Fa,mm,best,ev,loss){
    var tk=GM.tk;
    GM.rv=true;GM.skip=false;GM.busy=true;GM.lastLb=loss>=200?'b':'i';
    var rec={at:GM.hist.length-1,lb:GM.lastLb,sans:[mm.san]};GM.curRec=rec;   /* شاخه‌ی اشتباه برای ثبت نهایی */
    gmR();gmUi();
    var head='❌ اشتباه: '+mm.san+'\nارزیابی از دید تو از '+fmt(best)+' به '+fmt(ev)+' رسید.';
    gmSt(head+'\nانجین ادامه‌ی بازی رو نشونت می‌ده...');
    if(!await gmSl(1500,tk))return;
    var r=await geP(Fa,1,CFG.dep);
    if(tk!==GM.tk)return;
    var pv=(r.L&&r.L[1]&&r.L[1].pv)||[],sans=pvS(Fa,pv,2*CFG.rl-1),applied=0,i,u,m;
    for(i=0;i<sans.length&&!GM.skip;i++){
      u=pv[i];
      m=GM.g.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]});
      if(!m)break;
      applied++;rec.sans.push(m.san);GM.last=[m.from,m.to];GM.lastLb=null;gmR(m);
      gmSt(head+'\n'+lineTxt(Fp,[mm.san].concat(sans.slice(0,applied))));
      if(!await gmSl(CFG.spd,tk))return;
    }
    if(!GM.skip&&!await gmSl(1600,tk))return;
    GM.br.push(rec);GM.curRec=null;
    while(applied-->0)GM.g.undo();
    gmRevert();           /* حرکت اشتباهِ خودت هم برمی‌گرده */
    GM.rv=false;GM.skip=false;GM.busy=false;
    gmR();gmUi();
    gmSt('✋ برگشتیم به همون موقعیت.\nحالا دوباره تلاش کن و حرکت درست رو پیدا کن.');
  }
  function gmReveal(Fp,P){
    var tk=GM.tk,ks=skeys(P),best=cpv(P[ks[0]]),thr=Math.round(CFG.thr*100);
    var ok=ks.filter(function(i){return best-cpv(P[i])<=thr}).slice(0,3);
    var txt=ok.map(function(i){return pvS(Fp,P[i].pv,1)[0]+' ('+fmt(cpv(P[i]))+')'}).join('، ');
    var u=P[ks[0]].pv[0],m=GM.g.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]});
    if(!m){GM.busy=false;gmUi();gmErr('حرکت پیشنهادی نامعتبر بود.');return}
    gmPush(m);GM.last=[m.from,m.to];GM.lastLb=null;GM.ty='f';GM.sel=null;GM.rt=null;GM.rv=false;GM.busy=true;GM.st.shown++;
    GM.note='💡 حرکت درست: '+txt+'.\n'+m.san+' رو برات زدم و بازی ادامه پیدا می‌کنه.';
    gmR(m);gmUi();gmSt(GM.note);
    setTimeout(function(){if(tk===GM.tk)gmNext()},1800);
  }
  g$('gmshow').onclick=function(){
    if(!gmCan()||GM.mode!=='play')return;
    var tk=GM.tk,Fp=GM.g.fen();
    GM.busy=true;gmUi();gmSt('در حال پیدا کردن حرکت درست...');
    geEval(Fp,8,CFG.dep,function(P,err){
      if(tk!==GM.tk)return;
      if(!P||!P[1]){gmErr(err);return}
      gmReveal(Fp,P);
    });
  };
  g$('gmskip').onclick=function(){if(GM&&GM.rv)GM.skip=true};
  g$('gmretry').onclick=function(){if(GM&&GM.mode==='play'){GM.err=false;gmNext()}};
  function gmEnd(){
    GM.mode='over';GM.busy=false;GM.rv=false;
    var g=GM.g,msg;
    if(g.in_checkmate())msg=g.turn()===GM.color?'مات شدی. انجین برد.':'مات کردی! 🎉 تو بردی.';
    else if(g.in_stalemate())msg='پات؛ بازی مساوی شد.';
    else if(g.insufficient_material())msg='مهره‌ی کافی برای مات نیست؛ مساوی.';
    else if(g.in_threefold_repetition())msg='تکرار سه‌باره؛ مساوی.';
    else msg='بازی مساوی شد.';
    GM.result=msg.split('\n')[0];GM.pre=null;GM.psel=null;GM.vfy=false;
    msg+='\nاشتباه‌ها: '+GM.st.mis+' · حرکت‌هایی که نشونت دادم: '+GM.st.shown;
    gmUi();gmSt(msg);
  }
  function gmToSetup(){
    geAbort();GM.tk++;GM.rv=false;GM.skip=false;GM.busy=false;GM.err=false;GM.rt=null;GM.mode='setup';
    GM.vfy=false;GM.curRec=null;GM.pre=null;GM.psel=null;GM.clk=null;
    GM.ply=GM.hist.length;gmBuild();gmUi();gmSt('');
