  g$('gmgo').onclick=gmStartGame;

  /* =====================================================================
     افزوده‌ها: ساعت بازی · پایان بازی · ثبت بازی (با شاخه‌های اشتباه) · پیش‌حرکت
     ===================================================================== */

  /* ---------- ساعت ---------- */
  function gmClkInit(){
    var m=/^(\d+)\+(\d+)$/.exec(CFG.tc||'off');
    if(!m){GM.clk=null;return}
    GM.cm=GM.ce=(+m[1])*60000;GM.cinc=(+m[2])*1000;GM.clk={t:Date.now()};
  }
  function fmtT(ms){
    ms=Math.max(0,ms);
    if(ms<10000)return (ms/1000).toFixed(1);
    var s=Math.ceil(ms/1000),m=Math.floor(s/60);s=s%60;
    return m+':'+(s<10?'0':'')+s;
  }
  // کدام ساعت می‌دود؟ فقط وقتی «فکر کردن» واقعی در جریانه (نه بررسی حرکت، نه مرور اشتباه)
  function gmRunning(){
    if(!GM||GM.mode!=='play'||GM.rv||GM.vfy||GM.err)return null;
    if(GM.g.turn()===GM.color)return GM.busy?null:'m';
    return GM.busy?'e':null;
  }
  function gmClkUi(r){
    if(!GM||!GM.clk)return;
    var e=g$('gmckE'),m=g$('gmckM');
    e.textContent=fmtT(GM.ce);m.textContent=fmtT(GM.cm);
    e.classList.toggle('on',r==='e');m.classList.toggle('on',r==='m');
    e.classList.toggle('lo',GM.ce<20000);m.classList.toggle('lo',GM.cm<20000);
  }
  function gmTick(){
    if(!GM||!GM.clk)return;
    var now=Date.now(),dt=now-GM.clk.t,r=null;GM.clk.t=now;
    if(GM.mode==='play'){r=gmRunning();if(r==='m')GM.cm-=dt;else if(r==='e')GM.ce-=dt}
    gmClkUi(r);
    if(GM.mode==='play'){
      if(GM.cm<=0){GM.cm=0;gmFinish('flagm')}
      else if(GM.ce<=0){GM.ce=0;gmFinish('flage')}
