/* LINER-UPDATE id="keep-awake" title="روشن ماندن همیشگی صفحه" base="v6" */
(function () {
  if (window.__keepAwake) return;
  var KA = window.__keepAwake = { lock: null, vid: null, timer: null };

  // روش اصلی: Screen Wake Lock API (نیاز به https یا localhost؛ روی گیت‌هاب‌پیجز کار می‌کنه)
  function acquire() {
    if (document.visibilityState !== 'visible') return;
    if (KA.lock) return;
    if (navigator.wakeLock && navigator.wakeLock.request) {
      navigator.wakeLock.request('screen').then(function (l) {
        KA.lock = l;
        l.addEventListener('release', function () { KA.lock = null; });
      }).catch(function () { fallback(); });
    } else {
      fallback();
    }
  }

  // روش پشتیبان: ویدیوی نامرئی که مرورگر برای پخشش صفحه رو روشن نگه می‌داره
  function fallback() {
    if (KA.vid) { try { KA.vid.play(); } catch (e) {} return; }
    try {
      var c = document.createElement('canvas');
      c.width = c.height = 16;
      var x = c.getContext('2d');
      if (!c.captureStream) return;
      var v = document.createElement('video');
      v.setAttribute('playsinline', '');
      v.muted = true; v.loop = true;
      v.srcObject = c.captureStream(5);
      v.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:.01;pointer-events:none;z-index:-1';
      document.body.appendChild(v);
      var n = 0;
      setInterval(function () { n++; x.fillStyle = n % 2 ? '#000' : '#010101'; x.fillRect(0, 0, 16, 16); }, 1000);
      var p = v.play(); if (p && p.catch) p.catch(function () {});
      KA.vid = v;
    } catch (e) {}
  }

  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'visible') { KA.lock = null; acquire(); }
  });
  window.addEventListener('focus', acquire);
  window.addEventListener('pageshow', acquire);
  // بعضی مرورگرها بدون اولین لمس اجازه نمی‌دن؛ با اولین تعامل دوباره تلاش می‌کنیم
  ['pointerdown', 'touchstart', 'click', 'keydown'].forEach(function (ev) {
    document.addEventListener(ev, function () { acquire(); if (KA.vid) { try { KA.vid.play(); } catch (e) {} } }, { passive: true });
  });
  // هر ۲۰ ثانیه چک می‌کنه قفل از دست نرفته باشه
  KA.timer = setInterval(acquire, 20000);

  acquire();
})();

