/* LINER-UPDATE id="liner-ui-1" title="دکمه‌های برچسب بالای صفحه + چک‌باکس زیر صفحه + برچسب طرف خودم" base="v6"
 * این اپدیت سه کار می‌کند:
 * ۱) در ویرایش، دکمه‌های «بی‌دقتی / بلندر / درست» بالای صفحه‌ی شطرنج قرار می‌گیرند (همیشه در دسترس).
 * ۲) چک‌باکس «تحلیل زنده با ستاک‌فیش و نوار ارزیابی» دقیقاً زیر صفحه‌ی شطرنج می‌آید (ویرایش و مرور)؛
 *    لاین‌ها، پیشنهادهای حرکت و کاندیدهای استاک‌فیش سر جای خودشان می‌مانند.
 * ۳) دکمه‌ی جدید «درست !» اضافه می‌شود و برچسب‌ها برای حرکات طرف خودت هم اعمال و در تمرین و مرور دیده می‌شوند
 *    (هایلایت خانه‌ی حرکت + پیام وضعیت + علامت در لیست حرکات + پاپ‌آپ در مرور).
 */
(function () {
  var LOG = '[liner-ui-1]';
  function $(i) { return document.getElementById(i); }
  function safe(name, fn) { try { fn(); } catch (e) { console.warn(LOG, name, (e && e.message) || e); } }
  /* جایگزینی امنِ یک تکه از بدنه‌ی یک تابع سراسری (اگر الگو پیدا نشد، فقط هشدار می‌دهد و ادامه می‌دهد) */
  function rp(name, a, b) {
    safe('patch:' + name, function () {
      var f = window[name];
      if (typeof f !== 'function') { console.warn(LOG, 'تابع پیدا نشد:', name); return; }
      var s = f.toString();
      if (s.indexOf(a) < 0) { console.warn(LOG, 'الگو در تابع پیدا نشد:', name); return; }
      (0, eval)('window.' + name + '=(' + s.replace(a, function () { return b; }) + ')');
    });
  }

  var LB_MY = { b: 'حرکتِ آخرِ خودت بلندر (??) علامت خورد', i: 'حرکتِ آخرِ خودت بی‌دقتی (?!) علامت خورد', g: 'حرکتِ آخرِ خودت درست (!) علامت خورد' };
  var LB_RV = { b: 'این حرکت بلندر (??) علامت خورده', i: 'این حرکت بی‌دقتی (?!) علامت خورده', g: 'این حرکت درست (!) علامت خورده' };
  window.LINER_LB = { MY: LB_MY, RV: LB_RV };

  /* ---------- CSS ---------- */
  safe('css', function () {
    if ($('lu-css')) return;
    var t = document.createElement('style');
    t.id = 'lu-css';
    t.textContent = [
      '#lbar{margin-top:8px}',
      '#lbar button{flex:1 1 0;min-width:0}',
      '#lg.on{background:#2ecc71;border-color:#2ecc71;color:#000}',
      '.lbg{color:#2ecc71}',
      'button.bl.lbg,.chip.bl.lbg,.chip.lbg{color:#2ecc71!important;border-color:#2ecc71!important}',
      '.sq.last.lk-g::before{background:rgba(46,204,113,.85)}',
      '#ed>.bw+label.tgl,#rv>.bw+label.tgl{margin:8px 0 6px}'
    ].join('');
    document.head.appendChild(t);
  });

  /* ---------- ۱) ویرایش: انتقال دکمه‌های برچسب به بالای صفحه + افزودن دکمه‌ی «درست» ---------- */
  safe('layout:ed', function () {
    var ed = $('ed'), bw = ed.querySelector('.bw');
    if (!bw) throw new Error('.bw در ویرایش پیدا نشد');
    var li = $('li'), lb = $('lb');
    if (!li || !lb) throw new Error('#li/#lb پیدا نشد');
    var lbar = $('lbar');
    if (!lbar) {
      lbar = document.createElement('div');
      lbar.id = 'lbar'; lbar.className = 'bar';
      var lg = $('lg') || document.createElement('button');
      lg.id = 'lg'; lg.type = 'button';
      lg.textContent = 'درست !';
      lg.title = 'حرکت درست/خوب (!) — روی آخرین حرکتِ واردشده ثبت می‌شود. دوباره بزنی برمی‌دارد.';
      lbar.appendChild(li); lbar.appendChild(lb); lbar.appendChild(lg);
      ed.insertBefore(lbar, bw);
      var mp = null, ps = ed.querySelectorAll('p.meta'), i;
      for (i = 0; i < ps.length; i++) if (ps[i].textContent.indexOf('برچسب روی آخرین حرکت') > -1) { mp = ps[i]; break; }
      if (mp) ed.insertBefore(mp, lbar);
      lg.onclick = function () { setLb('g'); };
    }
    /* چک‌باکس «تحلیل زنده» دقیقاً زیر صفحه‌ی شطرنج (ویرایش) */
    var t2 = $('eon2') ? $('eon2').parentNode : null;
    if (t2) bw.parentNode.insertBefore(t2, bw.nextSibling);
  });

  /* ---------- ۲) مرور: چک‌باکس «تحلیل زنده» دقیقاً زیر صفحه‌ی شطرنج ---------- */
  safe('layout:rv', function () {
    var rv = $('rv'), bw3 = rv.querySelector('.bw');
    if (!bw3) throw new Error('.bw در مرور پیدا نشد');
    var t3 = $('eon3') ? $('eon3').parentNode : null;
    if (t3) bw3.parentNode.insertBefore(t3, bw3.nextSibling);
  });

  /* ---------- ۳) برچسب «درست !» ---------- */
  window.lbs = function (n) { return !n || !n.lb ? '' : n.lb === 'b' ? '??' : n.lb === 'i' ? '?!' : n.lb === 'g' ? '!' : ''; };
  safe('lg:click', function () { if ($('lg') && window.setLb) $('lg').onclick = function () { setLb('g'); }; });
  safe('upEd:wrap', function () {
    var _u = window.upEd;
    window.upEd = function () {
      var r = _u ? _u.apply(this, arguments) : undefined;
      try { var lg = $('lg'); if (lg) lg.className = (window.E && E.path && E.path.length && E.node && E.node.lb === 'g') ? 'on' : ''; } catch (e) { }
      return r;
    };
  });

  /* ---------- ۴) PGN: پذیرفتن علامت «!» هنگام وارد کردن لاین ---------- */
  rp('parseTree', 'mm=x.match(/(\\?\\?|\\?!)[!?]*$/);', 'mm=x.match(/(\\?\\?|\\?!)[!?]*$|!$/);');
  rp('parseTree', "if(mm)lb=mm[1]==='??'?'b':'i';", "if(mm)lb=mm[0]==='!'?'g':(mm[1]==='??'?'b':'i');");

  /* ---------- ۵) تمرین: برچسب‌ها برای حرکاتِ طرفِ خود کاربر هم دیده شوند ---------- */
  window.pMove = function (cand, sq) {
    var c = P.node.c, av = avail(P.node), ok = cand.filter(function (m) { return av.some(function (x) { return x.san === m.san; }); })[0];
    if (ok) {
      var mm = P.g.move({ from: ok.from, to: ok.to, promotion: ok.promotion });
      P.node = c.filter(function (x) { return x.san === ok.san; })[0]; P.path.push(P.node);
      P.um++; if (!P.bad) P.ok1++; P.bad = false; P.lastLb = P.node.lb || null;
      if (P.node.lb) { P.myNote = LB_MY[P.node.lb]; P.myKeep = LB_MY[P.node.lb]; }
      P.last = [ok.from, ok.to]; P.sel = null; P.hint = null; P.hn = 0; render(mm); next();
    } else if (cand.some(function (m) { return c.some(function (x) { return x.san === m.san; }); })) {
      P.sel = null; render(); st('این شاخه رو قبلاً کامل رفتی. شاخه‌ی نرفته: ' + sn(av) + '.');
    } else {
      pmAdd('wrong', cand[0] && cand[0].san); P.miss++; P.bad = true; P.line.errs = (P.line.errs || 0) + 1; save(); mark(P.line.id); P.sel = null; P.wrong = sq;
      st('این حرکت توی لاین نیست. دوباره امتحان کن.'); render();
      setTimeout(function () { if (P) { P.wrong = null; B = P; render(); } }, 500);
    }
  };

  window.next = function () {
    var c = P.node.c, rn = P.rwn ? P.rwn + ' ' : ''; P.rwn = '';
    if (!mine() && P.myNote) { rn += (rn ? ' ' : '') + P.myNote + ' '; P.myNote = ''; }
    brs(null); pprog(); ml();
    if (!c.length) { leaf(); return; }
    var av = avail(P.node);
    if (!mine()) {
      P.busy = true;
      if (av.length > 1) {
        P.choose = true; st(rn + 'حریف اینجا ' + av.length + ' شاخه‌ی نرفته داره. کدوم رو بازی کنم؟');
        $('brs').innerHTML = av.map(function (x) { return '<button class="chip bl lb' + (x.lb || '') + '" data-i="' + c.indexOf(x) + '">' + esc(x.san + lbs(x)) + '</button>'; }).join('');
        $('brs').classList.add('pop'); placePop();
        return;
      }
      st(rn + '...'); oppPlay(av[0], rn ? 900 : 520);
    } else {
      st(rn + (av.length > 1 ? 'اینجا ' + av.length + ' شاخه‌ی نرفته داری' + (S.showBr ? ':' : '.') + ' هر کدوم رو دوست داری برو.' : 'نوبت توئه. مهره رو انتخاب کن.'));
      if (P.note) { st(P.note + ' ' + $('st').textContent); P.note = ''; }
      if (P.myKeep) { st(P.myKeep + ' ' + $('st').textContent); P.myKeep = ''; }
      brs(av);
    }
  };

  window.rewind = function (i) {
    var g = newGame(P.line), k;
    P.path = P.path.slice(0, i + 1);
    for (k = 1; k <= i; k++) g.move(P.path[k].san);
    var h = g.history({ verbose: true }), lm = h[h.length - 1];
    P.g = g; P.node = P.path[i]; P.last = lm ? [lm.from, lm.to] : null; P.lastLb = (P.node && P.node.lb) || null; P.sel = null; P.hint = null; P.wrong = null; P.hn = 0; P.bad = false; P.choose = false; P.busy = false; P.done = false; P.tk++;
    P.myNote = ''; P.myKeep = '';
    B = P; render();
  };

  window.oppPlay = function (ch, delay) {
    var me = P, tk = P.tk; P.busy = true;
    setTimeout(function () {
      if (P !== me || P.tk !== tk) return;
      var m = P.g.move(ch.san);
      P.node = ch; P.path.push(ch); P.last = [m.from, m.to]; P.busy = false; P.hint = null; B = P;
      P.lastLb = ch.lb || null;
      if (ch.lb) P.note = ch.lb === 'b' ? 'حریف بلندر زد!' : ch.lb === 'i' ? 'حریف بی‌دقتی کرد.' : 'حریف حرکت درستی زد.';
      render(m); next();
    }, delay);
  };

  /* ---------- ۶) مرور: پاپ‌آپ برچسب هنگام رسیدن به حرکت علامت‌خورده ---------- */
  window.rvGo = function (ch) {
    var m = V.g.move(ch.san);
    V.path.push(V.node); V.sans.push(ch.san); V.node = ch; V.last = [m.from, m.to]; V.lastLb = ch.lb || null; V.ty = ch.ty || null; V.shk = !!ch.ty; B = V; render(m); upRv();
    if (ch.lb && V.path.length && !ch.nt && !V.fm.length && !V.free) showNote(LB_RV[ch.lb] || '');
  };

  /* ---------- ۷) نمودار درختی: علامت و رنگ «درست» ---------- */
  rp('gxDraw', "if(m.lb==='b')lb='b';else if(m.lb==='i'&&lb!=='b')lb='i';", "if(m.lb==='b')lb='b';else if(m.lb==='i'&&lb!=='b')lb='i';else if(m.lb==='g'&&!lb)lb='g';");
  rp('gxDraw', "var stroke=lb==='b'?'#ff6b62':lb==='i'?'#e6a23c':on?'#4fb3a5':'#555d6b'", "var stroke=lb==='b'?'#ff6b62':lb==='i'?'#e6a23c':lb==='g'?'#2ecc71':on?'#4fb3a5':'#555d6b'");
  rp('gxDraw', "var lab=isRoot?'شروع':rep.san+(lb==='b'?'??':lb==='i'?'?!':'');", "var lab=isRoot?'شروع':rep.san+(lb==='b'?'??':lb==='i'?'?!':lb==='g'?'!':'');");
  rp('gvDetail', "esc(c.san+(c.lb==='b'?'??':c.lb==='i'?'?!':''))", "esc(c.san+(c.lb==='b'?'??':c.lb==='i'?'?!':c.lb==='g'?'!':''))");

  console.log(LOG, 'نصب شد ✓');
})();

/* LINER-UPDATE id="move-lines-db-v1" title="انتخاب دیتابیس در ایجاد + انتقال لاین‌ها بین دسته‌ها و دیتابیس" base="v6" */
(function () {
  if (window.__LINER_MVDB) return;
  window.__LINER_MVDB = 1;

  var LIMIT = 50000;          // حداکثر تعداد شاخه‌ی قابل تبدیل به بازی‌های دیتابیس
  var MV = { id: null, busy: false };

  LU.css(
    '#mvm{position:fixed;inset:0;z-index:9990;background:rgba(0,0,0,.65);display:flex;align-items:center;justify-content:center;padding:12px}' +
    '#mvm[hidden]{display:none}' +
    '#mvm .tyb{width:min(480px,100%);max-height:92dvh;overflow:auto}' +
    '#mvm button{width:100%;margin:4px 0}'
  );
  LU.html('body', 'beforeend',
    '<div id="mvm" hidden><div class="tyb" role="dialog" aria-modal="true" aria-labelledby="mvt">' +
    '<h3 id="mvt"></h3><div id="mvb"></div><div class="meta" id="mvi"></div>' +
    '<button id="mvx">لغو</button></div></div>');

  function closeMv() { if (MV.busy) return; $('mvm').hidden = true; MV.id = null; $('mvi').textContent = ''; }
  $('mvx').onclick = closeMv;
  $('mvm').onclick = function (e) { if (e.target === this) closeMv(); };

  /* ---------- ساخت بازی‌های PGN از درخت لاین (هر شاخه = یک بازی) ---------- */
  function lineBlocks(l) {
    var f = (l.fen || '').split(' '), turn = f[1] || 'w', num = parseInt(f[5], 10) || 1;
    var nm = String(l.name || 'line').replace(/"/g, "'"), paths = [];
    (function w(n, p) {
      if (paths.length >= LIMIT) return;
      if (!n.c.length) { if (p.length) paths.push(p); return; }
      n.c.forEach(function (x) { w(x, p.concat([x])); });
    })(l.tree, []);
    return paths.map(function (p, i) {
      var t = turn, n = num, first = true, mv = [];
      p.forEach(function (nd) {
        if (t === 'w') mv.push(n + '. ' + nd.san);
        else { mv.push(first ? n + '... ' + nd.san : nd.san); n++; }
        first = false; t = (t === 'w') ? 'b' : 'w';
      });
      var h = '[Event "' + nm + '"]\n[Site "Patterner"]\n[White "' + nm + '"]\n[Black "شاخه ' + (i + 1) + '"]\n[Result "*"]\n';
      if (l.fen) h += '[SetUp "1"]\n[FEN "' + l.fen + '"]\n';
      return h + '\n' + mv.join(' ') + ' *\n';
    });
  }

  // ذخیره‌ی یک دیتابیس تازه (همان مسیر «بارگذاری PGN»؛ اسم تکراری با پسوند (۲) ذخیره می‌شود)
  function dbSave(name, blocks, onProg) {
    return dbIndex(blocks, onProg).then(function (rec) {
      if (!rec.games.length) throw new Error('بازی معتبری ساخته نشد.');
      var base = name, k = 2;
      while (DBS.some(function (d) { return d.name === name; })) name = base + ' (' + (k++) + ')';
      var id = 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      rec.id = id;
      var meta = { id: id, name: name, n: rec.games.length, u: rec.P.length, ts: Date.now() };
      return dbPut(meta, rec).then(function () {
        DBC[id] = rec;
        DBS = DBS.filter(function (d) { return d.id !== id; }).concat([meta]).sort(function (a, b) { return a.ts - b.ts; });
        return meta;
      });
    });
  }

  /* ---------- انتقال ---------- */
  function openMv(id) {
    var l = byId(id); if (!l) return;
    MV.id = id;
    var cats = CATS.slice();
    S.lines.forEach(function (x) { if (x.cat && cats.indexOf(x.cat) < 0) cats.push(x.cat); });
    $('mvt').textContent = 'انتقال «' + l.name + '»';
    var h = '<div class="meta">دسته‌ی فعلی: ' + esc(l.cat || '') + '</div>';
    cats.filter(function (c) { return c !== l.cat; }).forEach(function (c) {
      h += '<button data-d="c" data-v="' + esc(c) + '">' + esc(c) + '</button>';
    });
    h += '<hr style="opacity:.25"><div class="meta">' + esc(DBN) + ': هر شاخه‌ی لاین یک بازی می‌شود. دیتابیس‌ها فقط روی همین دستگاه ذخیره می‌شوند و با گیت‌هاب همگام نمی‌شوند.</div>' +
      '<button class="p" data-d="dbc">کپی به ' + esc(DBN) + ' (لاین می‌مونه)</button>' +
      '<button class="d" data-d="dbm">انتقال به ' + esc(DBN) + ' (از لاین‌ها حذف می‌شه)</button>';
    $('mvb').innerHTML = h;
    $('mvi').textContent = '';
    $('mvm').hidden = false;
  }

  function toDb(l, remove) {
    var blocks = lineBlocks(l);
    if (!blocks.length) { toast('این لاین حرکتی ندارد.'); return; }
    if (remove && blocks.length >= LIMIT) { toast('این لاین بیشتر از ' + LIMIT + ' شاخه دارد؛ فقط «کپی» ممکنه.'); return; }
    if (DBL.busy) { toast('یه دیتابیس در حال پردازشه؛ کمی صبر کن.'); return; }
    MV.busy = true; DBL.busy = true;
    $('mvi').textContent = 'در حال ساخت دیتابیس...';
    dbSave(l.name, blocks, function (i, n) { $('mvi').textContent = 'پردازش: ' + i + ' از ' + n + ' بازی'; })
      .then(function (meta) {
        DBL.busy = false; MV.busy = false;
        if (remove) { S.lines = S.lines.filter(function (x) { return x.id !== l.id; }); save(); markRm(l.id); }
        closeMv();
        UI.open = true; UI.cat = DBN; DBV = null; renderLib();
        toast((remove ? 'منتقل شد' : 'کپی شد') + ' به دیتابیس: ' + meta.n + ' بازی.');
      })
      .catch(function (e) {
        DBL.busy = false; MV.busy = false;
        $('mvi').textContent = 'خطا: ' + (e && e.message || e);
      });
  }

  $('mvb').onclick = function (e) {
    var t = e.target, d = t.dataset && t.dataset.d;
    if (!d || MV.busy) return;
    var l = byId(MV.id); if (!l) { closeMv(); return; }
    if (d === 'c') {
      l.cat = t.dataset.v; l.ut = Date.now(); save(); mark(l.id);
      closeMv(); UI.open = true; UI.cat = l.cat; renderLib();
      toast('منتقل شد به «' + l.cat + '».');
    } else if (d === 'dbc') toDb(l, false);
    else if (d === 'dbm') {
      if (window.liner_pwAsk) window.liner_pwAsk('رمز انتقال به دیتابیس (حذف از لاین‌ها)', function () { toDb(l, true); });
      else toDb(l, true);
    }
  };

  // دکمه‌ی «انتقال» در هر ردیف
  try {
    LU.patch('rowHtml', '<button class="own" data-a="ed" data-v="\'+l.id+\'">ویرایش</button>',
      '<button class="own" data-a="mvl" data-v="\'+l.id+\'">انتقال</button><button class="own" data-a="ed" data-v="\'+l.id+\'">ویرایش</button>');
  } catch (e) { console.error('patch rowHtml', e); }
  var _lc = $('list').onclick;
  $('list').onclick = function (e) {
    var t = e.target;
    if (t.dataset && t.dataset.a === 'mvl') { openMv(t.dataset.v); return; }
    return _lc.apply(this, arguments);
  };

  /* ---------- «ایجاد»: انتخاب دسته‌ی دیتابیس ---------- */
  var _fill = window.fillCats;
  window.fillCats = function () {
    var a = $('c'), v = a ? a.value : '';
    _fill.apply(this, arguments);
    if (!a) return;
    if (!Array.prototype.some.call(a.options, function (o) { return o.value === DBN; }))
      a.insertAdjacentHTML('beforeend', '<option value="' + esc(DBN) + '">' + esc(DBN) + '</option>');
    if (v === DBN) a.value = DBN;
  };

  var _doAdd = window.doAdd;
  window.doAdd = function () {
    if ($('c').value !== DBN) return _doAdd.apply(this, arguments);
    var name = $('n').value.trim(), txt = $('p').value.trim(), m = $('am');
    m.textContent = ''; m.style.color = '';
    if (!name) { m.textContent = 'اسم رو وارد کن.'; return; }
    if (!txt) { m.textContent = 'برای دیتابیس، PGN رو وارد کن (می‌تونه چند بازی باشه).'; return; }
    if (DBL.busy) { m.textContent = 'یه دیتابیس در حال پردازشه؛ کمی صبر کن.'; return; }
    var bl = pgnBlocks(txt);
