/* LINER-UPDATE id="move-sounds" title="صدای حرکت‌ها و اشتباه" base="v6" */
/*
  صداها: حرکت عادی، گرفتن مهره، قلعه، کیش، مات، و «اشتباه در تمرین».
  - صدای حرکت با هر حرکت روی تخته (تمرین، ادیتور، مرور، خودکار) پخش می‌شه.
  - صدای اشتباه فقط وقتی پخش می‌شه که در حالت تمرین، حرکتِ زده‌شده
    توی لاین نباشه (همون‌جایی که پیام «این حرکت توی لاین نیست» می‌آد).
  - همه‌ی آدرس‌ها اینجان، پس با همگام‌سازی روی همه‌ی دستگاه‌ها نصب می‌شن.

  اولویت صدا: مات > کیش > قلعه > گرفتن مهره > حرکت عادی
  اگه فایلی لود نشه، یه صدای داخلی ساده به‌جای اون پخش می‌شه.
*/
(function(){
  if(window.__lsnd)return;
  ['render','toast'].forEach(function(n){if(typeof window[n]!=='function')throw new Error('تابع '+n+' پیدا نشد؛ این اپدیت برای نسخه‌ی v6 ساخته شده.')});

  var SOUNDS={
    move:    'https://cdn.imgurl.ir/uploads/t176057_Fmove.mp3',
    capture: 'https://cdn.imgurl.ir/uploads/i68380_Capa.mp3',
    castle:  'https://cdn.imgurl.ir/uploads/g40595_A.mp3',
    check:   'https://cdn.imgurl.ir/uploads/m55725_Chack.mp3',
    mate:    'https://cdn.imgurl.ir/uploads/w790754_Chack_Mate.mp3',
    wrong:   'https://cdn.imgurl.ir/uploads/e328741_.mp3'
  };

  var LS='lt_snd',CF={on:true,vol:1};
  try{var sv=JSON.parse(localStorage.getItem(LS)||'null');if(sv){if(typeof sv.on==='boolean')CF.on=sv.on;if(typeof sv.vol==='number'&&isFinite(sv.vol))CF.vol=Math.max(0,Math.min(1,sv.vol))}}catch(e){}
  function saveCf(){try{localStorage.setItem(LS,JSON.stringify(CF))}catch(e){}}

  /* ---- صدای داخلی (فقط وقتی آدرس لود نشد یا نبود) ---- */
  var AC=null;
  function ctx(){
    if(AC)return AC;
    try{var C=window.AudioContext||window.webkitAudioContext;if(C)AC=new C()}catch(e){}
    return AC;
  }
  function synth(kind){
    var c=ctx();if(!c)return;
    try{
      if(c.state==='suspended')c.resume();
      var t=c.currentTime,dur=(kind==='capture'||kind==='wrong')?.13:.08,
          n=Math.floor(c.sampleRate*dur),buf=c.createBuffer(1,n,c.sampleRate),
          d=buf.getChannelData(0),i;
      for(i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,kind==='capture'?2.2:3.2);
      var s=c.createBufferSource();s.buffer=buf;
      var f=c.createBiquadFilter();f.type='bandpass';
      f.frequency.value=kind==='capture'?650:kind==='wrong'?320:1100;
      f.Q.value=kind==='capture'?.9:1.4;
      var g=c.createGain();g.gain.value=(kind==='capture'?1.6:1.1)*CF.vol;
      s.connect(f);f.connect(g);g.connect(c.destination);s.start(t);
    }catch(e){}
  }

  /* ---- فایل‌های صدا ---- */
  var AU={},BAD={};
  Object.keys(SOUNDS).forEach(function(k){
    if(!SOUNDS[k])return;
    try{
      var a=new Audio();a.preload='auto';a.src=SOUNDS[k];
      a.addEventListener('error',function(){BAD[k]=true});
      AU[k]=a;
    }catch(e){BAD[k]=true}
  });
  function play(kind){
    if(!CF.on||CF.vol<=0)return;
    var a=AU[kind];
    if(!a||BAD[kind]){synth(kind);return}
    try{
      a.volume=CF.vol;a.currentTime=0;
      var p=a.play();
      if(p&&p.catch)p.catch(function(){synth(kind)});
    }catch(e){synth(kind)}
  }
  function kindOf(m){
    var san=m.san||'',fl=m.flags||'';
    if(san.indexOf('#')>-1)return 'mate';
    if(san.indexOf('+')>-1)return 'check';
    if(fl.indexOf('k')>-1||fl.indexOf('q')>-1)return 'castle';
    if(m.captured||fl.indexOf('c')>-1||fl.indexOf('e')>-1)return 'capture';
    return 'move';
  }

  /* ---- صدای حرکت: هر بار تخته رندر می‌شه و حرکت جدیدی هست ---- */
  var _render=window.render,lastMv=null;
  window.render=function(mv){
    var r=_render.apply(this,arguments);
    try{
      if(mv&&typeof mv==='object'&&mv.from&&mv.to&&mv!==lastMv&&!window.JP){
        lastMv=mv;play(kindOf(mv));
      }
    }catch(e){}
    return r;
  };

  /* ---- صدای اشتباه: پیام مخصوص اشتباه در تمرین را رهگیری می‌کنیم ---- */
  var _st=window.st;
  if(typeof _st==='function'){
    window.st=function(t){
      try{
        if(typeof t==='string'&&t.indexOf('این حرکت توی لاین نیست')===0)play('wrong');
      }catch(e){}
      return _st.apply(this,arguments);
    };
  }

  window.__lsnd={play:play,kindOf:kindOf,cfg:CF,sounds:SOUNDS};

  /* ---- تنظیمات توی صفحه‌ی اصلی ---- */
  var css=document.createElement('style');
  css.textContent='#sndbox [hidden]{display:none!important}#sndbox input[type=range]{padding:0;margin:8px 0}';
  document.head.appendChild(css);
  var h='<details id="sndbox"><summary>صدای حرکت‌ها</summary>'+
    '<label class="tgl" style="margin:10px 0 6px"><input type="checkbox" id="sndon"> صدای حرکت‌ها روشن باشه</label>'+
    '<label for="sndvol">بلندی صدا</label><input id="sndvol" type="range" min="0" max="100" step="5">'+
    '<div class="bar" style="margin-top:6px">'+
      '<button id="sndt1">حرکت</button>'+
      '<button id="sndt2">گرفتن</button>'+
      '<button id="sndt3">قلعه</button>'+
      '<button id="sndt4">کیش</button>'+
      '<button id="sndt5">مات</button>'+
      '<button id="sndt6">اشتباه</button>'+
    '</div>'+
    '<p class="meta">صدای «اشتباه» فقط در حالت تمرین پخش می‌شه، وقتی حرکتی می‌زنی که توی لاین نیست. آدرس همه‌ی صداها (حرکت، گرفتن، قلعه، کیش، مات و اشتباه) توی خود اپدیت ثبت شده و با همگام‌سازی روی بقیه‌ی دستگاه‌ها هم نصب می‌شن.</p>'+
  '</details>';
  var anchor=document.getElementById('engbox');
  if(anchor)anchor.insertAdjacentHTML('beforebegin',h);
  else{var lst=document.getElementById('list');if(lst)lst.insertAdjacentHTML('afterend',h);else throw new Error('جای تنظیمات صدا پیدا نشد')}
  var on=document.getElementById('sndon'),vol=document.getElementById('sndvol');
  on.checked=CF.on;vol.value=String(Math.round(CF.vol*100));
  on.onchange=function(){CF.on=this.checked;saveCf()};
  vol.onchange=vol.oninput=function(){CF.vol=Math.max(0,Math.min(1,(+this.value||0)/100));saveCf()};
  ['move','capture','castle','check','mate','wrong'].forEach(function(k,i){
    document.getElementById('sndt'+(i+1)).onclick=function(){var o=CF.on;CF.on=true;play(k);CF.on=o};
  });
})();

