  /* ==========================================================
     راست‌کلیک
     ========================================================== */
  [bd, bdg].forEach(function (el) {
    if (!el) return;
    el.addEventListener('contextmenu', function (e) {
      if (!PM_ON) return;
      var ctx;
      try { ctx = el === bd ? getPracticeCtx() : getEngineCtx(); } catch (x) { return; }
      if (!ctx || !ctx.queue.length) return;
      e.preventDefault();
      ctx.queue.length = 0;
      ctx.setSel(null);
      ctx.render();
      toast('پیش‌حرکت‌ها لغو شد.');
    });
  });

  /* ==========================================================
     Render hook
     ========================================================== */
  var _render = window.render;
  window.render = function () {
    var r = _render.apply(this, arguments);
    try { paintNow(); } catch (e) { console.error('[v7]', e); }
    return r;
  };

  function paintNow() {
    if (isDragging()) {
      if (!DRAG || !DRAG.canDrag) return;
      var boardEl = DRAG.boardEl;
      var pe = boardEl.querySelector('[data-s="' + DRAG.sq + '"] .pc');
      if (pe) {
        var isMine = pe.className.indexOf(DRAG.ctx.myColor) > -1;
        if (isMine) {
          pe.style.visibility = 'hidden';
          DRAG.pe = pe;
        }
      }
      Object.keys(DRAG.legalTargets).forEach(function (s) {
        var el = boardEl.querySelector('[data-s="' + s + '"]');
        if (el) el.classList.add('t');
      });
      return;
    }

    var p = getPracticeCtx();
    if (p && (p.queue.length || p.getSel())) {
      var v = buildVirtual(p.fen, p.queue, p.myColor);
      if (v.validCount < p.queue.length) p.queue.length = v.validCount;
      paintBoard(p.boardEl, v, p.queue, p.getSel(), p.myColor);
    }

    var g = getEngineCtx();
    if (g && (g.queue.length || g.getSel())) {
      var v2 = buildVirtual(g.fen, g.queue, g.myColor);
      if (v2.validCount < g.queue.length) g.queue.length = v2.validCount;
      paintBoard(g.boardEl, v2, g.queue, g.getSel(), g.myColor);
    }
  }

  /* ==========================================================
     اجرای پریمو
     ========================================================== */
  setInterval(function () {
    if (!PM_ON) return;

    try {
      var p = getPracticeCtx();
      if (p) {
        var P = window.P;
        if (P.wrong && p.queue.length) {
          p.queue.length = 0;
          p.setSel(null);
          try { render(); } catch (e) {}
          toast('حرکت اشتباه بود؛ پیش‌حرکت‌های باقی‌مانده لغو شد.');
        } else if (p.queue.length && p.isMyTurn && !P.busy && !P.done && !P.wrong && !isDragging()) {
          execPractice(p);
        }
      }
    } catch (e) { console.error('[v7] practice poll:', e); }

    try {
      var g = getEngineCtx();
      if (g) {
        var GM = g.gm;
        if (GM.rt && g.queue.length) {
          g.queue.length = 0;
          g.setSel(null);
          try { render(); } catch (e) {}
          toast('حرکت اشتباه بود؛ پیش‌حرکت‌های باقی‌مانده لغو شد.');
        } else if (g.queue.length && g.isMyTurn && !GM.busy && !GM.rv && !GM.vfy && !GM.err && GM.mode === 'play' && !GM._v7Exec && !isDragging()) {
          execEngine(g);
        }
      }
    } catch (e) { console.error('[v7] engine poll:', e); }
  }, 100);

  function execPractice(ctx) {
    var P = window.P;
    if (!P || !ctx.queue.length) return;
    var pre = ctx.queue[0];
    var cand = P.g.moves({ verbose: true }).filter(function (m) { return m.from === pre.from && m.to === pre.to; });
    if (!cand.length) {
      ctx.queue.length = 0;
      toast('پیش‌حرکت قانونی نبود؛ بقیه لغو شد.');
      try { render(); } catch (e) {}
      return;
    }
    ctx.queue.shift();
    var orig = window.noAnim;
    window.noAnim = true;
    try {
      if (typeof pMove === 'function') pMove(cand, pre.to);
      else { var m = P.g.move({ from: pre.from, to: pre.to, promotion: pre.to[1] === '8' || pre.to[1] === '1' ? 'q' : undefined }); if (m) render(m); }
    } catch (e) { console.error('[v7] practice exec:', e); }
    finally { window.noAnim = orig; }
  }

  function execEngine(ctx) {
    var GM = ctx.gm;
    if (!GM || !ctx.queue.length) return;
    var pre = ctx.queue[0];
    var cand = GM.g.moves({ verbose: true }).filter(function (m) { return m.from === pre.from && m.to === pre.to; });
    if (!cand.length) {
      ctx.queue.length = 0;
      toast('پیش‌حرکت قانونی نبود؛ بقیه لغو شد.');
      try { render(); } catch (e) {}
      return;
    }
    ctx.queue.shift();
    GM._v7Exec = true;
    GM.sel = pre.from;
    var targetEl = document.getElementById('bdg').querySelector('[data-s="' + pre.to + '"]');
    if (!targetEl) { GM._v7Exec = false; GM.sel = null; return; }
    try {
      var ev = new MouseEvent('click', { bubbles: true, cancelable: true });
      targetEl.dispatchEvent(ev);
    } catch (e) { console.error('[v7] engine dispatch:', e); }
    setTimeout(function () { GM._v7Exec = false; }, 300);
  }

  /* ==========================================================
     دکمه
     ========================================================== */
  function buildButton() {
    var old = document.getElementById('v7prmbtn');
    if (old) old.remove();

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'v7prmbtn';
    btn.style.cssText = 'display:block;margin:8px auto;padding:6px 14px;font-size:13px;border-radius:8px';
    var hint = document.getElementById('hint');
    if (hint) hint.insertAdjacentElement('afterend', btn);
    else {
      var prac = document.getElementById('prac');
      if (prac) prac.insertBefore(btn, prac.firstChild);
    }

    btn.onclick = function () {
      PM_ON = !PM_ON;
      try { localStorage.setItem('lt_prm', PM_ON ? '1' : '0'); } catch (e) {}
      if (!PM_ON) {
        var p = getPracticeCtx(); if (p) { p.queue.length = 0; p.setSel(null); }
        var g = getEngineCtx(); if (g) { g.queue.length = 0; g.setSel(null); }
        try { render(); } catch (e) {}
      }
      updBtn();
      toast(PM_ON ? 'پریمو روشن شد' : 'پریمو خاموش شد');
    };

    function updBtn() {
      var n = 0;
      var p = getPracticeCtx(); if (p) n = p.queue.length;
      else { var g = getEngineCtx(); if (g) n = g.queue.length; }
      btn.textContent = '⚡ پریمو: ' + (PM_ON ? 'روشن' : 'خاموش') + (n ? ' (' + n + ')' : '');
      btn.style.background = PM_ON ? 'var(--acc)' : '';
      btn.style.color = PM_ON ? '#fff' : '';
      btn.style.borderColor = PM_ON ? 'var(--acc)' : '';
    }
    updBtn();
    setInterval(updBtn, 400);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', buildButton);
  else buildButton();

  /* ==========================================================
     Escape
     ========================================================== */
  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape') return;
    if (isDragging()) { cancelDrag(); e.preventDefault(); return; }
    var p = getPracticeCtx();
    if (p && p.queue.length) { p.queue.length = 0; p.setSel(null); try { render(); } catch (x) {} toast('پیش‌حرکت‌ها لغو شد.'); return; }
    var g = getEngineCtx();
    if (g && g.queue.length) { g.queue.length = 0; g.setSel(null); try { render(); } catch (x) {} toast('پیش‌حرکت‌ها لغو شد.'); }
  });

  console.log('[premove-v7.2] loaded successfully');

  } catch (fatal) {
    console.error('[premove-v7.2] FATAL:', fatal);
    try { toast('خطای راه‌اندازی پریمو: ' + (fatal.message || fatal), 6000); } catch (x) {}
  }
})();

