/* LINER-UPDATE id="remember-pw-v1" title="یادآوری رمز: با یک تیک در تنظیمات، روی همین دستگاه دیگه رمز ویرایش/حذف پرسیده نمی‌شه" base="v6" */
(function () {
  if (window.__LINER_REMPW) return;
  window.__LINER_REMPW = 1;

  var KEY = 'lt_pw_remember';   // فقط روی همین دستگاه/مرورگر ذخیره می‌شه (با گیت‌هاب همگام نمی‌شه)

  function on() { try { return localStorage.getItem(KEY) === '1'; } catch (e) { return false; } }
  function setOn(v) { try { if (v) localStorage.setItem(KEY, '1'); else localStorage.removeItem(KEY); return true; } catch (e) { return false; } }

  /* ---------- قلاب روی پرسش رمز: اگه یادآوری روشن باشه، مستقیم کار اجرا می‌شه ---------- */
  function wrap(orig) {
    if (typeof orig !== 'function' || orig.__rempw) return orig;
    var f = function (title, fn) {
      if (on() && typeof fn === 'function') return fn.call(this);
      return orig.apply(this, arguments);
    };
    f.__rempw = 1;
    f.__orig = orig;
    return f;
  }
  function origAsk() {
    var f = window.liner_pwAsk;
    return typeof f === 'function' ? (f.__orig || f) : null;
  }

  (function hook() {
    var val = wrap(window.liner_pwAsk);
    try {
      Object.defineProperty(window, 'liner_pwAsk', {
        configurable: true, enumerable: true,
        get: function () { return val; },
        set: function (v) { val = typeof v === 'function' ? wrap(v) : v; }
      });
    } catch (e) {
      if (typeof val === 'function') window.liner_pwAsk = val;   // اگه تبدیل به accessor ممکن نبود
    }
  })();

  /* ---------- رابط: یک گروه در پنجره‌ی ⚙️ تنظیمات ---------- */
  var body = document.querySelector('#settings-panel .settings-body');
  if (!body) throw new Error('بخش تنظیمات پیدا نشد');
  body.insertAdjacentHTML('beforeend',
    '<div class="settings-group" id="pwr-g"><h3>🔑 یادآوری رمز روی این دستگاه</h3>' +
    '<p>با روشن کردن این تیک (و وارد کردن رمزت)، از این به بعد روی همین دستگاه برای ویرایش و حذف رمز پرسیده نمی‌شه، تا وقتی که تیک رو برداری.</p>' +
    '<label class="tgl"><input type="checkbox" id="pwron"> رمز رو روی این دستگاه یادآوری کن</label>' +
    '<div id="pwrm" role="status" aria-live="polite" style="min-height:1.5em;font-weight:bold"></div></div>');

  var cb = document.getElementById('pwron'), msg = document.getElementById('pwrm');
  function say(t, bad) { msg.textContent = t; msg.style.color = bad ? '#c0392b' : '#16803c'; }
  function sync() { cb.checked = on(); }
  sync();

  cb.onchange = function () {
    if (!this.checked) {                      // برداشتن تیک: بدون رمز
      setOn(false);
      say('یادآوری خاموش شد؛ دوباره رمز پرسیده می‌شه.');
      return;
    }
    this.checked = false;                     // تا وقتی رمز تأیید نشده روشن نمی‌مونه
    var ask = origAsk();
    if (!ask) { say('سیستم رمز پیدا نشد (liner_pwAsk تعریف نشده)؛ چیزی روشن نشد.', true); return; }
    ask.call(window, 'رمز برای یادآوری روی این دستگاه', function () {
      if (setOn(true)) { cb.checked = true; say('✓ روشن شد؛ روی این دستگاه دیگه رمز نمی‌پرسه.'); }
      else say('ذخیره روی این دستگاه ممکن نشد (حافظه‌ی مرورگر بسته است).', true);
    });
  };

  var _open = window.openSettings;
  if (typeof _open === 'function') {
    window.openSettings = function () { var r = _open.apply(this, arguments); try { sync(); } catch (e) { } return r; };
  }
})();

