    '.whypop.why b{font:800 1em/1 system-ui,Vazirmatn,sans-serif;direction:ltr;color:#ff2d2d;padding:.18em .42em;border:.08em solid #ff2d2d;border-radius:.35em;background:rgba(255,45,45,.14);text-shadow:0 0 .35em rgba(255,0,0,.45)}' +
    '.whypop.ok b{font:800 1em/1 system-ui,Vazirmatn,sans-serif;padding:.18em .4em;border:.08em solid #20b26b;border-radius:.35em;background:rgba(32,178,107,.18);color:#20b26b;text-shadow:0 0 .3em rgba(32,178,107,.4)}' +
    '.why-choice-shade{position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box}' +
    '.why-choice{width:min(390px,100%);box-sizing:border-box;background:var(--card,#101318);color:var(--fg,#e8ecf1);border:1px solid rgba(128,128,128,.35);border-radius:16px;padding:20px;box-shadow:0 16px 55px rgba(0,0,0,.5);text-align:center;font-family:system-ui,Vazirmatn,sans-serif}' +
    '.why-choice-title{font-size:1.12rem;font-weight:800;margin-bottom:9px}' +
