    '.why-no{background:#666;color:#fff}'
  );

  function spd(){var s=document.getElementById('rspd');return (s&&+s.value)||1100}
  function reduced(){return !!(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)}
  function valid(w){return w.x===P&&!$('prac').hidden}
  function cfgOf(l){
    var c=l&&l.tree&&l.tree.wy;
    if(!c||(c.s!=='w'&&c.s!=='b'))return null;
    var th=+c.th;if(!(th>0))th=WY_DEF;
    return {s:c.s,th:th};
  }
  function whiteCp(L,fen){
    var sg=fen.split(' ')[1]==='w'?1:-1;
    var v=L.t==='mate'?(L.v>0?10000-L.v:-10000-L.v):L.v;
    return v*sg;
  }
  function pvList(pv){
    return pv.slice(0,WY_PLIES).map(function(u){
      var o={f:u.slice(0,2),t:u.slice(2,4)};
      if(u[4])o.p=u[4];
      return o;
    });
  }

  /* ================== صف انجین ================== */
  var WE = { ev: {}, q: [], job: null, tries: 0, wd: null, rt: null, warned: false };

  function weFail(j){(j.cb||[]).forEach(function(f){try{f(null)}catch(e){console.error(e)}})}
  function weFinish(j,res){
    if(res&&res.d>=WY_DEPTH-4)WE.ev[j.k]=res;
    (j.cb||[]).forEach(function(f){try{f(res)}catch(e){console.error(e)}});
  }
  function weAsk(fen,cb){
    var k=fen.split(' ').slice(0,4).join(' '),hit=WE.ev[k];
    if(hit){cb(hit);return}
    try{
      var g=new Chess(fen);
      if(g.in_checkmate()){cb({w:g.turn()==='w'?-10000:10000,pv:[],d:99});return}
      if(g.game_over()){cb({w:0,pv:[],d:99});return}
    }catch(e){cb(null);return}
    var j=(WE.job&&WE.job.k===k)?WE.job:WE.q.filter(function(x){return x.k===k})[0];
    if(j){j.cb.push(cb);return}
    WE.q.push({fen:fen,k:k,cb:[cb]});
    weKick();
  }
  function weKick(){
    clearTimeout(WE.rt);
    if(WE.job||!WE.q.length)return;
    if(!window.EN){
      if(!WE.warned){WE.warned=true;if(window.toast)toast('برای Why خودکار، انجین ستاک‌فیش لازم است.',6000)}
      var a0=WE.q;WE.q=[];a0.forEach(weFail);return;
    }
    if(!EN.w){
      if(!window.ENG_SRC||!ENG_SRC.full){
        if(!WE.warned){WE.warned=true;if(window.toast)toast('اول فایل‌های انجین ستاک‌فیش را از تنظیمات بارگذاری کن.',6000)}
        var a1=WE.q;WE.q=[];a1.forEach(weFail);return;
      }
      engEnsure();
    }
    if(!EN.w||!EN.ready||(window.SA&&SA.run)){
      if(++WE.tries>240){WE.tries=0;var a2=WE.q;WE.q=[];a2.forEach(weFail);return}
      WE.rt=setTimeout(weKick,250);return;
    }
    WE.tries=0;
    var j=WE.q.shift();
    WE.job=j;j.sc=null;j.pv=null;j.d=0;
    clearTimeout(WE.wd);
    WE.wd=setTimeout(function(){
      if(WE.job!==j)return;
      engSend('stop');
      WE.wd=setTimeout(function(){
        if(WE.job!==j)return;
        WE.job=null;EN.busy=false;weFail(j);weKick();
      },3000);
    },20000);
    if(EN.busy){j.st='wait';EN.pend=null;EN.stp=true;engSend('stop')}
    else weGo();
  }
  function weGo(){
    var j=WE.job;if(!j)return;
    j.st='run';EN.busy=true;EN.stp=false;EN.sfen=null;
    engSend('setoption name MultiPV value 1');
    engSend('position fen '+j.fen);
    engSend('go depth '+WY_DEPTH);
  }
  var _engLine=window.engLine;
  window.engLine=function(s){
    var j=WE.job;
    if(!j||(window.SA&&SA.run))return _engLine.apply(this,arguments);
    if(typeof s!=='string')s=String(s);
    if(j.st==='wait'){
      var r=_engLine.apply(this,arguments);
      if(s.indexOf('bestmove')===0)weGo();
      return r;
    }
    if(s.indexOf('bestmove')===0){
      clearTimeout(WE.wd);
      EN.busy=false;EN.stp=false;WE.job=null;
      var res=null;
      if(j.sc&&j.d>=6)res={w:whiteCp(j.sc,j.fen),pv:j.pv||[],d:j.d};
      if(res)weFinish(j,res);else weFail(j);
      if(EN.pend)engGo();
      weKick();
      return;
    }
    if(s.indexOf('info')===0){
      if(s.indexOf(' lowerbound')>0||s.indexOf(' upperbound')>0)return;
      var mp=s.match(/ multipv (\d+)/);
      if(mp&&+mp[1]!==1)return;
      var sc=s.match(/ score (cp|mate) (-?\d+)/),pv=s.match(/ pv (.+)$/),dp=s.match(/ depth (\d+)/);
      if(!sc||!pv)return;
      j.sc={t:sc[1],v:+sc[2]};
      j.pv=pv[1].trim().split(' ');
      j.d=dp?+dp[1]:j.d;
      return;
    }
    return _engLine.apply(this,arguments);
  };

  /* ================== پاپ‌آپ ================== */
  function pop(x,kind){
    if(!x||!x.el)return null;
    var r=x.el.getBoundingClientRect();
    if(!r.width)return null;
    var box=document.createElement('div');
    box.className='whypop '+kind;
    box.setAttribute('aria-hidden','true');
    box.style.left=(r.left+r.width/2)+'px';
    box.style.top=(r.top+r.height/2)+'px';
    box.style.fontSize=(r.width*(kind==='why'?0.075:0.14))+'px';
    box.innerHTML=kind==='why'?'<b>Why</b>':'<b>OK</b>';
    document.body.appendChild(box);
    var rm=reduced();
    if(box.animate){
      box.animate(rm?[
        {transform:'translate(-50%,-50%) scale(1)',opacity:START_OP},
        {transform:'translate(-50%,-50%) scale(1)',opacity:0}
      ]:[
        {transform:'translate(-50%,-50%) scale(.25)',opacity:START_OP,offset:0},
        {transform:'translate(-50%,-50%) scale('+(END_SCALE*.55)+')',opacity:START_OP*.75,offset:.55},
        {transform:'translate(-50%,-50%) scale('+END_SCALE+')',opacity:0,offset:1}
      ],{duration:rm?500:DUR,easing:'cubic-bezier(.2,.7,.3,1)',fill:'forwards'});
    }
    setTimeout(function(){if(box.parentNode)box.parentNode.removeChild(box)},DUR+150);
    return box;
  }

  /* ================== دیالوگ بله/خیر ================== */
  var choiceBox=null;
  function closeChoice(){
    if(choiceBox&&choiceBox.shade&&choiceBox.shade.parentNode)choiceBox.shade.parentNode.removeChild(choiceBox.shade);
    choiceBox=null;
  }
  function askChoice(x,onYes,onNo){
    closeChoice();
    var shade=document.createElement('div');
    shade.className='why-choice-shade';
    shade.innerHTML=
      '<div class="why-choice" role="dialog" aria-modal="true">'+
      '<div class="why-choice-title">این حرکت افت زیادی دارد</div>'+
      '<div class="why-choice-text">ادامهٔ پیشنهادی انجین تا ۴ حرکت کامل نمایش داده شود؟</div>'+
      '<div class="why-choice-buttons">'+
      '<button type="button" data-why="yes" class="why-yes">بله، نمایش بده</button>'+
      '<button type="button" data-why="no" class="why-no">خیر، ادامهٔ تمرین</button>'+
      '</div></div>';
    document.body.appendChild(shade);
    choiceBox={shade:shade,onNo:onNo,x:x};
    shade.querySelector('[data-why="yes"]').onclick=function(){
      if(!choiceBox||choiceBox.shade!==shade)return;
      closeChoice();
      if(P===x)onYes();
    };
    shade.querySelector('[data-why="no"]').onclick=function(){
      if(!choiceBox||choiceBox.shade!==shade)return;
      closeChoice();
      if(P===x)onNo();
    };
  }
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'&&choiceBox){
      var cb=choiceBox;closeChoice();
      if(P===cb.x&&cb.onNo)cb.onNo();
    }
  });

  /* ================== پخش دمو ================== */
  function stopPlay(){
    var w=WY.cur;
    if(!w)return;
    WY.cur=null;
    clearTimeout(w.tm);
    if(w.pe&&w.pe.parentNode)w.pe.parentNode.removeChild(w.pe);
  }
  function playOnly(x,list,head,done){
    stopPlay();
    var g;
    try{g=new Chess(x.g.fen())}catch(e){if(done)done();return}
    var w={x:x,g:x.g,tm:null,pe:null,tk:x.tk};
    WY.cur=w;
    x.busy=true;x.sel=null;x.hint=null;x.wrong=null;
    w.pe=pop(x,'why');
    var seq=[];
    function label(){if(window.st)st(head+(seq.join('  ')||'...'))}
    label();
    function fin(){
      if(WY.cur!==w)return;
      WY.cur=null;
      clearTimeout(w.tm);
      if(w.pe&&w.pe.parentNode)w.pe.parentNode.removeChild(w.pe);
      if(done)done();
    }
    function step(i){
      if(WY.cur!==w)return;
      if(x!==P||$('prac').hidden){stopPlay();return}
      if(x.tk!==w.tk){stopPlay();return}
      if(i>=list.length){w.tm=setTimeout(fin,END_HOLD);return}
      var d=list[i],m=null;
      try{m=g.move({from:d.f,to:d.t,promotion:d.p})}catch(e){m=null}
      if(!m){w.tm=setTimeout(fin,200);return}
      x.g=g;x.last=[m.from,m.to];x.lastLb=null;x.ty=null;x.shk=false;x.sel=null;
      B=x;render(m);
      seq.push(m.san);label();
      w.tm=setTimeout(function(){step(i+1)},spd());
    }
    w.tm=setTimeout(function(){step(0)},PRE);
  }

  /* ================== آنالیز خارج از لاین ================== */
  var pendingToken=0;

  function restoreAfter(a){
    var x=a.x;
    if(P!==x)return;
    if(x.tk!==a.tk)return;
    x.g=a.beforeGame;
    x.last=a.oldLast;
    x.lastLb=a.oldLastLb;
    x.ty=a.oldTy;
    x.hint=a.oldHint;
    x.sel=null;x.wrong=null;x.shk=false;x.busy=false;
    B=x;render();
    if(window.st)st('این حرکت توی لاین نیست. دوباره امتحان کن.');
  }

  function showContinuation(a,after){
    var x=a.x;
    if(P!==x||!valid({x:x})){if(P===x)x.busy=false;return}
    x.g=a.afterGame;
    x.last=[a.madeMove.from,a.madeMove.to];
    x.lastLb=null;x.ty=null;x.sel=null;x.hint=null;x.busy=true;
    B=x;render(a.madeMove);
    playOnly(x,pvList(after.pv||[]),'Why — افت ارزیابی '+(a.loss/100).toFixed(1)+' پیاده: ',function(){
      restoreAfter(a);
    });
  }

  function analyzeOffLine(a){
    var x=a.x;
    if(P!==x||x.done||$('prac').hidden)return;
    if(a.token!==pendingToken)return;

    x.busy=true;
    if(window.st)st('حرکت خارج از لاین است؛ انجین در حال بررسی افت ارزیابی...');

    var before=null,after=null,gotB=false,gotA=false,settled=false;

    var timer=setTimeout(function(){
      if(settled)return;
      settled=true;
      x.busy=false;
      if(window.st)st('این حرکت توی لاین نیست. ارزیابی انجین کامل نشد.');
    },WY_HOLD);

    function finish(){
      if(settled||!gotB||!gotA)return;
      settled=true;
      clearTimeout(timer);

      if(P!==x||x.done||$('prac').hidden||x.tk!==a.tk)return;
      if(a.token!==pendingToken)return;

      x.busy=false;

      if(!before||!after){
        if(window.st)st('این حرکت توی لاین نیست. ارزیابی در دسترس نبود.');
        return;
      }

      var sg=a.cfg.s==='w'?1:-1;
      var loss=(before.w-after.w)*sg;
      a.loss=loss;
      var thCp=Math.round(a.cfg.th*100);

      if(loss>=thCp){
        if(!after.pv||!after.pv.length){
          pop(x,'why');
          if(window.st)st('این حرکت توی لاین نیست؛ افت '+(loss/100).toFixed(1)+' پیاده.');
          return;
        }
        if(window.st)st('این حرکت توی لاین نیست؛ افت '+(loss/100).toFixed(1)+' پیاده.');
        x.busy=true;
        pop(x,'why');
        setTimeout(function(){
          if(P!==x||x.done||$('prac').hidden){if(P===x)x.busy=false;return}
          askChoice(x,
            function(){if(P!==x)return;showContinuation(a,after)},
            function(){if(P!==x)return;x.busy=false;if(window.st)st('این حرکت توی لاین نیست. دوباره امتحان کن.')}
          );
        },700);
      }else{
        pop(x,'ok');
        if(window.st)st('این حرکت توی لاین نیست (افت '+(loss/100).toFixed(1)+' پیاده). دوباره امتحان کن.');
      }
    }

    weAsk(a.fenBefore,function(r){before=r;gotB=true;finish()});
    weAsk(a.fenAfter,function(r){after=r;gotA=true;finish()});
  }

  /* ================== هوک pMove ================== */
  var _pMove=window.pMove;
  if(typeof _pMove==='function'){
    window.pMove=function(cand,sq){
      var x=P;
      var analysis=null;

      if(x&&x.g&&x.node&&!x.done&&!$('prac').hidden&&cand&&cand.length){
        var av=avail(x.node);
        var ok=cand.filter(function(m){return av.some(function(v){return v.san===m.san})})[0];
        if(!ok){
          var wasDone=cand.some(function(m){return x.node.c.some(function(v){return v.san===m.san})});
          if(!wasDone){
            var chosen=cand.filter(function(m){return !m.promotion||m.promotion==='q'})[0]||cand[0];
            var fenBefore=x.g.fen();
            try{
              var tmp=new Chess(fenBefore);
              var mvObj={from:chosen.from,to:chosen.to};
              if(chosen.promotion)mvObj.promotion=chosen.promotion;
              var madeMove=tmp.move(mvObj);
              if(madeMove){
                var cfg=cfgOf(x.line);
                if(cfg&&madeMove.color===cfg.s){
                  analysis={
                    x:x,cfg:cfg,
                    fenBefore:fenBefore,fenAfter:tmp.fen(),
                    beforeGame:x.g,afterGame:tmp,madeMove:madeMove,
                    oldLast:x.last,oldLastLb:x.lastLb,oldTy:x.ty,oldHint:x.hint,
                    token:++pendingToken,tk:x.tk
                  };
                }
              }
            }catch(e){console.error('[why] setup:',e)}
          }
        }
      }

      var ret=_pMove.apply(this,arguments);
      if(analysis)analyzeOffLine(analysis);
      return ret;
    };
  }

  /* ================== توقف دمو هنگام ناوبری ================== */
  if(typeof window.rewind==='function'){var _rw=window.rewind;window.rewind=function(){stopPlay();closeChoice();return _rw.apply(this,arguments)}}
  if(typeof window.start==='function'){var _st=window.start;window.start=function(){stopPlay();closeChoice();return _st.apply(this,arguments)}}
  try{
    var _b=document.getElementById('back');
    if(_b){var _bo=_b.onclick;_b.onclick=function(){stopPlay();closeChoice();if(_bo)return _bo.apply(this,arguments)}}
  }catch(e){}

  /* ================== UI تنظیم در ویرایش ================== */
  try{
    var ecat=document.getElementById('ecat');
    if(ecat&&!document.getElementById('ewy')){
      ecat.insertAdjacentHTML('afterend',
        '<div id="ewy" style="margin:10px 0"><label for="ewys">Why خودکار (با انجین)</label>'+
        '<div class="bar" style="margin-top:4px;align-items:center">'+
        '<select id="ewys" aria-label="طرفِ Why"><option value="">خاموش</option><option value="w">سفید</option><option value="b">سیاه</option></select>'+
        '<span class="meta" style="flex:0 0 auto">افت بیشتر از</span>'+
        '<input id="ewyv" type="number" min="0.1" max="9.9" step="0.1" value="0.8" inputmode="decimal" aria-label="پیاده" style="flex:1;min-width:0">'+
        '<span class="meta" style="flex:0 0 auto">پیاده</span></div>'+
        '<p class="meta" id="ewyi"></p></div>');

      var wyInfo=function(){
        var c=E&&E.t&&E.t.wy,m=document.getElementById('ewyi');
        if(!m)return;
        m.textContent=c?
          'در تمرین، اگر حرکتِ خارج از لاینِ '+(c.s==='w'?'سفید':'سیاه')+' افت ارزیابی بیش از '+c.th+' پیاده داشته باشد، Why پخش می‌شود. افت کمتر = علامت OK.':
          'خاموش. طرف را انتخاب کن تا در تمرین فعال شود.';
      };
      var wyLoad=function(){
        if(!E)return;
        var c=E.t&&E.t.wy;
        var s=document.getElementById('ewys'),v=document.getElementById('ewyv');
        if(s)s.value=c&&c.s?c.s:'';
        if(v)v.value=c&&c.th?c.th:WY_DEF;
        wyInfo();
      };
      var wySave=function(){
        if(!E)return;
        var s=document.getElementById('ewys').value;
        var th=parseFloat(String(document.getElementById('ewyv').value).replace(/[۰-۹]/g,function(c){return c.charCodeAt(0)-1776}).replace(',','.').replace('٫','.'));
        if(!(th>0))th=WY_DEF;
        th=Math.min(9.9,Math.max(0.1,Math.round(th*10)/10));
        document.getElementById('ewyv').value=th;
        if(s)E.t.wy={s:s,th:th};else delete E.t.wy;
        wyInfo();
      };
      document.getElementById('ewys').onchange=wySave;
      document.getElementById('ewyv').onchange=wySave;

      if(typeof window.openEdit==='function'){
        var _oe=window.openEdit;
        window.openEdit=function(){var r=_oe.apply(this,arguments);try{wyLoad()}catch(e){}return r};
      }
      try{wyLoad()}catch(e){}
    }
  }catch(e){console.error('[why] edit UI:',e)}

  console.log('[why-v1] ✓ loaded');
})();
